-- V69__cleanup_authors.sql
-- Consolidated author data cleanup for PostgreSQL/Flyway.
--
-- Safety properties:
--   * no persistent author/book IDs are hardcoded;
--   * Flyway owns the transaction (no BEGIN/COMMIT/ROLLBACK here);
--   * historical diagnostic-only/trial scripts are excluded;
--   * every scratch table is batch-prefixed (sXX_) and ON COMMIT DROP;
--   * semantic preconditions use normalized names and/or ISBNs;
--   * unexpected cardinalities raise exceptions before destructive steps.
--
-- IMPORTANT: validate on a recent production clone before applying to production.


-- ============================================================================
-- Historical cleanup batch Script-8
-- ============================================================================
DROP TABLE IF EXISTS pg_temp.s8_author_merge_rules;
DROP TABLE IF EXISTS pg_temp.s8_author_merges;

CREATE TEMP TABLE s8_author_merge_rules
(
    canonical_name_normalized VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    PRIMARY KEY (duplicate_name_normalized),
    CHECK (canonical_name_normalized <> duplicate_name_normalized)
) ON COMMIT DROP;

