CREATE TEMP TABLE s11_author_merges
(
    canonical_id BIGINT NOT NULL,
    duplicate_id BIGINT NOT NULL,
    PRIMARY KEY (duplicate_id),
    CHECK (canonical_id <> duplicate_id)
) ON COMMIT DROP;

INSERT INTO s11_author_merges (canonical_id, duplicate_id)
SELECT canonical.id,
       duplicate.id
FROM s11_author_merge_rules r
         JOIN authors canonical
              ON canonical.name_normalized = r.canonical_name_normalized
         JOIN authors duplicate
              ON duplicate.name_normalized = r.duplicate_name_normalized;



INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id,
       am.canonical_id
FROM s11_author_merges am
         JOIN book_authors ba
              ON ba.author_id = am.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;

DELETE
FROM book_authors ba
    USING s11_author_merges am
WHERE ba.author_id = am.duplicate_id;

DELETE
FROM authors a
    USING s11_author_merges am
WHERE a.id = am.duplicate_id;



