CREATE TEMP TABLE s14_author_merges
(
    canonical_id BIGINT       NOT NULL,
    duplicate_id BIGINT       NOT NULL,
    final_name   VARCHAR(255) NOT NULL,
    PRIMARY KEY (duplicate_id)
) ON COMMIT DROP;

INSERT INTO s14_author_merges (canonical_id, duplicate_id, final_name)
SELECT c.id, d.id, r.final_name
FROM s14_author_merge_rules r
         JOIN authors c ON c.name_normalized = r.canonical_name_normalized
         JOIN authors d ON d.name_normalized = r.duplicate_name_normalized;



INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id, am.canonical_id
FROM s14_author_merges am
         JOIN book_authors ba ON ba.author_id = am.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;

DELETE
FROM book_authors ba
    USING s14_author_merges am
WHERE ba.author_id = am.duplicate_id;

DELETE
FROM authors a
    USING s14_author_merges am
WHERE a.id = am.duplicate_id;

-- Corrige el nombre visible del registro conservado.
-- @PreUpdate de JPA no participa en SQL directo, por eso actualizamos también
-- name_normalized explícitamente con la misma normalización básica esperada.
UPDATE authors a
SET name            = am.final_name,
    name_normalized = trim(
            regexp_replace(
                    regexp_replace(lower(unaccent(am.final_name)), '[^a-z0-9]+', ' ', 'g'),
                    '\s+', ' ', 'g'
            )
                      )
FROM s14_author_merges am
WHERE a.id = am.canonical_id;


