-- =========================================================

DROP TABLE IF EXISTS pg_temp.s15_cherryl_drabble_variants;

CREATE TEMP TABLE s15_cherryl_drabble_variants
(
    name_normalized VARCHAR(255) PRIMARY KEY
) ON COMMIT DROP;

INSERT INTO s15_cherryl_drabble_variants (name_normalized)
VALUES ('cherryl drabbe'),
       ('drabbe cherryl'),
       ('cherryl drabble');


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s15_cherryl_drabble_variants v
                            LEFT JOIN authors a
                                      ON a.name_normalized = v.name_normalized
                   GROUP BY v.name_normalized
                   HAVING COUNT(a.id) > 1) THEN
            RAISE EXCEPTION
                'V69/Script-15: alguna variante de Cherryl Drabble resuelve ambiguamente';
        END IF;

        IF NOT EXISTS (SELECT 1
                       FROM s15_cherryl_drabble_variants v
                                JOIN authors a
                                     ON a.name_normalized = v.name_normalized) THEN
            RAISE EXCEPTION
                'V69/Script-15: no se encontró ninguna variante de Cherryl Drabble';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s15_cherryl_drabble_resolved;

CREATE TEMP TABLE s15_cherryl_drabble_resolved ON COMMIT DROP AS
SELECT a.id,
       a.name,
       a.name_normalized,
       COUNT(DISTINCT ba.book_id) AS book_count
FROM s15_cherryl_drabble_variants v
         JOIN authors a
              ON a.name_normalized = v.name_normalized
         LEFT JOIN book_authors ba
                   ON ba.author_id = a.id
GROUP BY a.id,
         a.name,
         a.name_normalized;


DROP TABLE IF EXISTS pg_temp.s15_cherryl_drabble_canonical;

CREATE TEMP TABLE s15_cherryl_drabble_canonical ON COMMIT DROP AS
SELECT id AS canonical_id
FROM s15_cherryl_drabble_resolved
ORDER BY CASE
             WHEN name_normalized = 'cherryl drabble' THEN 0
             ELSE 1
             END,
         book_count DESC,
         id ASC
LIMIT 1;


INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                c.canonical_id
FROM s15_cherryl_drabble_resolved r
         CROSS JOIN s15_cherryl_drabble_canonical c
         JOIN book_authors ba
              ON ba.author_id = r.id
WHERE r.id <> c.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s15_cherryl_drabble_resolved r,
        s15_cherryl_drabble_canonical c
WHERE ba.author_id = r.id
  AND r.id <> c.canonical_id;


DELETE
FROM authors a
    USING s15_cherryl_drabble_resolved r,
        s15_cherryl_drabble_canonical c
WHERE a.id = r.id
  AND r.id <> c.canonical_id;


UPDATE authors a
SET name            = 'Cherryl Drabble',
    name_normalized = 'cherryl drabble'
FROM s15_cherryl_drabble_canonical c
WHERE a.id = c.canonical_id;


