-- ============================================================
-- ESTADOS FINALES CONOCIDOS DE SCRIPTS POSTERIORES
-- ============================================================
-- Algunos scripts posteriores pueden reemplazar el
-- name_normalized histórico de Script-15 por otro definitivo.
--
-- En una reejecución completa de V69:
--
-- histórico presente  -> Script-15 puede procesarlo normalmente.
-- histórico ausente
-- final presente       -> ya fue consolidado por un script posterior.
--
-- Nunca aceptamos que ambos estados estén ausentes.
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s15_final_aliases;

CREATE TEMP TABLE s15_final_aliases
(
    historical_name_normalized VARCHAR(255) PRIMARY KEY,
    final_name                 VARCHAR(255) NOT NULL,
    final_name_normalized      VARCHAR(255) NOT NULL UNIQUE
) ON COMMIT DROP;


INSERT INTO s15_final_aliases (historical_name_normalized,
                               final_name,
                               final_name_normalized)
VALUES ('oram hiawyn', 'Hiawyn Oram', 'hiawyn oram'),
       ('peio agirre', 'Peio Aguirre', 'peio aguirre');


-- ============================================================
-- REGLAS EFECTIVAS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s15_effective_rules;

CREATE TEMP TABLE s15_effective_rules ON COMMIT DROP AS
SELECT r.name_normalized AS historical_name_normalized,
       COALESCE(
               fa.final_name,
               r.final_name
       )                 AS final_name,
       COALESCE(
               fa.final_name_normalized,
               r.name_normalized
       )                 AS final_name_normalized
FROM s15_merge_rules r
         LEFT JOIN s15_final_aliases fa
                   ON fa.historical_name_normalized = r.name_normalized;


-- ============================================================
-- A) VALIDAR AMBIGÜEDAD
-- ============================================================
-- Histórico:
--   puede existir 0, 1 o 2 veces.
--
-- Final:
--   puede existir 0 o 1 vez.
--
-- No permitimos:
--   >2 históricos
--   >1 final
-- ============================================================

DO
$$
    DECLARE
        invalid_rules TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               'historical=%s, historical_matches=%s, final=%s, final_matches=%s',
                               x.historical_name_normalized,
                               x.historical_matches,
                               x.final_name_normalized,
                               x.final_matches
                       ),
                       ' | '
                       ORDER BY x.historical_name_normalized
               )
        INTO invalid_rules
        FROM (SELECT er.historical_name_normalized,
                     er.final_name_normalized,

                     (SELECT COUNT(*)
                      FROM authors a
                      WHERE a.name_normalized =
                            er.historical_name_normalized) AS historical_matches,

                     (SELECT COUNT(*)
                      FROM authors a
                      WHERE a.name_normalized =
                            er.final_name_normalized)      AS final_matches

              FROM s15_effective_rules er) x
        WHERE x.historical_matches > 2
           OR x.final_matches > 1;

        IF invalid_rules IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-15 resolución ambigua: %',
                invalid_rules;
        END IF;
    END
$$;


-- ============================================================
-- B) TODA REGLA DEBE RESOLVER AL MENOS UN AUTOR
-- ============================================================
-- Casos válidos:
--
-- Primera ejecución:
--   histórico = 1..2
--
-- Reejecución después del propio Script-15:
--   histórico = 1
--
-- Reejecución después de un script posterior que renombró:
--   histórico = 0
--   final      = 1
-- ============================================================

DO
$$
    DECLARE
        unresolved TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               'historical=%s, final=%s',
                               er.historical_name_normalized,
                               er.final_name_normalized
                       ),
                       ' | '
                       ORDER BY er.historical_name_normalized
               )
        INTO unresolved
        FROM s15_effective_rules er
        WHERE NOT EXISTS (SELECT 1
                          FROM authors a
                          WHERE a.name_normalized =
                                er.historical_name_normalized
                             OR a.name_normalized =
                                er.final_name_normalized);

        IF unresolved IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-15 reglas sin resolver: %',
                unresolved;
        END IF;
    END
$$;


-- ============================================================
-- C) RESOLVER EL CANÓNICO
-- ============================================================
-- Si ya existe el name_normalized final de un alias posterior,
-- ese registro gana.
--
-- En el estado histórico normal se conserva la selección
-- original por final_name + id.
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s15_resolved;

CREATE TEMP TABLE s15_resolved ON COMMIT DROP AS
WITH candidates AS (SELECT er.historical_name_normalized,
                           er.final_name,
                           er.final_name_normalized,

                           a.id,
                           a.name,
                           a.name_normalized,

                           ROW_NUMBER() OVER (
                               PARTITION BY er.historical_name_normalized
                               ORDER BY
                                   CASE
                                       WHEN a.name_normalized = er.final_name_normalized
                                           THEN 0
                                       ELSE 1
                                       END,

                                   CASE
                                       WHEN a.name = er.final_name
                                           THEN 0
                                       ELSE 1
                                       END,

                                   a.id
                               ) AS rn

                    FROM s15_effective_rules er

                             JOIN authors a
                                  ON a.name_normalized = er.historical_name_normalized
                                      OR a.name_normalized = er.final_name_normalized)

SELECT historical_name_normalized,
       final_name,
       final_name_normalized,
       MAX(id) FILTER (WHERE rn = 1) AS canonical_id
FROM candidates
GROUP BY historical_name_normalized,
         final_name,
         final_name_normalized;


-- ============================================================
-- D) COPIAR TODAS LAS RELACIONES AL CANÓNICO
-- ============================================================

INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                r.canonical_id
FROM s15_resolved r
         JOIN authors a
              ON (
                     a.name_normalized = r.historical_name_normalized
                         OR a.name_normalized = r.final_name_normalized
                     )
                  AND a.id <> r.canonical_id
         JOIN book_authors ba
              ON ba.author_id = a.id
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- E) BORRAR RELACIONES DE LOS REGISTROS NO CANÓNICOS
-- ============================================================

DELETE
FROM book_authors ba
    USING s15_resolved r,
        authors a
WHERE (
    a.name_normalized = r.historical_name_normalized
        OR a.name_normalized = r.final_name_normalized
    )
  AND a.id <> r.canonical_id
  AND ba.author_id = a.id;


-- ============================================================
-- F) VALIDAR QUE NO QUEDEN RELACIONES EN DUPLICADOS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s15_resolved r
                            JOIN authors a
                                 ON (
                                        a.name_normalized = r.historical_name_normalized
                                            OR a.name_normalized = r.final_name_normalized
                                        )
                                     AND a.id <> r.canonical_id
                            JOIN book_authors ba
                                 ON ba.author_id = a.id) THEN
            RAISE EXCEPTION
                'V69/Script-15: duplicate author relationships remain after reassignment';
        END IF;
    END
$$;


-- ============================================================
-- G) BORRAR REGISTROS NO CANÓNICOS
-- ============================================================

DELETE
FROM authors a
    USING s15_resolved r
WHERE (
    a.name_normalized = r.historical_name_normalized
        OR a.name_normalized = r.final_name_normalized
    )
  AND a.id <> r.canonical_id;


-- ============================================================
-- H) APLICAR ESTADO FINAL
-- ============================================================
-- Para reglas normales:
-- final_name_normalized = historical_name_normalized.
--
-- Para aliases posteriores:
-- se conserva el estado definitivo posterior.
--
-- Ejemplo:
-- ORAM HIAWYN / oram hiawyn
--      ->
-- Hiawyn Oram / hiawyn oram
-- ============================================================

UPDATE authors a
SET name            = r.final_name,
    name_normalized = r.final_name_normalized
FROM s15_resolved r
WHERE a.id = r.canonical_id
  AND (
    a.name IS DISTINCT FROM r.final_name
        OR a.name_normalized IS DISTINCT FROM r.final_name_normalized
    );


-- ============================================================
-- I) POSTCONDICIÓN
-- ============================================================
-- Cada regla debe terminar con:
--
-- exactamente 1 autor final
-- y
-- 0 variantes históricas si el histórico y final son distintos.
-- ============================================================

DO
$$
    DECLARE
        invalid_rules TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               'historical=%s, final=%s, final_matches=%s, historical_remaining=%s',
                               er.historical_name_normalized,
                               er.final_name_normalized,
                               (SELECT COUNT(*)
                                FROM authors a
                                WHERE a.name_normalized =
                                      er.final_name_normalized),
                               (SELECT COUNT(*)
                                FROM authors a
                                WHERE a.name_normalized =
                                      er.historical_name_normalized
                                  AND er.historical_name_normalized <>
                                      er.final_name_normalized)
                       ),
                       ' | '
                       ORDER BY er.historical_name_normalized
               )
        INTO invalid_rules
        FROM s15_effective_rules er
        WHERE (SELECT COUNT(*)
               FROM authors a
               WHERE a.name_normalized =
                     er.final_name_normalized) <> 1
           OR (
            er.historical_name_normalized <>
            er.final_name_normalized
                AND EXISTS (SELECT 1
                            FROM authors a
                            WHERE a.name_normalized =
                                  er.historical_name_normalized)
            );

        IF invalid_rules IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-15 postcondición fallida: %',
                invalid_rules;
        END IF;
    END
$$;

