       a.name
FROM s16_target_authors t
         JOIN authors a
              ON a.name_normalized = t.name_normalized;


DROP TABLE IF EXISTS pg_temp.s16_target_book;
CREATE TEMP TABLE s16_target_book ON COMMIT DROP AS
SELECT id AS book_id,
       title
FROM books
WHERE title = 'IDEOLOGIA ALEMANA LA CAP I';


DO
$$
    BEGIN
        IF (SELECT COUNT(*) FROM s16_target_book) <> 1 THEN
            RAISE EXCEPTION
                'Abortado: IDEOLOGIA ALEMANA LA CAP I no resuelve exactamente a un libro';
        END IF;
    END
$$;

-- Agregar Karl Marx y Friedrich Engels.
INSERT INTO book_authors (book_id, author_id)
SELECT tb.book_id,
       ra.author_id
FROM s16_target_book tb
         CROSS JOIN s16_resolved_authors ra
ON CONFLICT (book_id, author_id) DO NOTHING;

-- Retirar la relación con "Marx, Engels".
DELETE
FROM book_authors ba
    USING authors a, s16_target_book tb
WHERE ba.author_id = a.id
  AND ba.book_id = tb.book_id
  AND a.name_normalized = 'marx engels';

-- Eliminar "Marx, Engels" si quedó huérfano.
DELETE
FROM authors a
WHERE a.name_normalized = 'marx engels'
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);



