VALUES ('HARDT', 'hardt michael'),
       ('NEGRI', 'antonio negri');


-- Resolver autores.
DROP TABLE IF EXISTS pg_temp.s17_resolved_authors;

CREATE TEMP TABLE s17_resolved_authors ON COMMIT DROP AS
SELECT t.author_key,
       a.id AS author_id,
       a.name
FROM s17_author_targets t
         JOIN authors a
              ON a.name_normalized = t.name_normalized;



DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s17_author_targets t
                            LEFT JOIN authors a
                                      ON a.name_normalized = t.name_normalized
                   GROUP BY t.author_key
                   HAVING COUNT(a.id) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: Hardt o Negri no resuelven exactamente a un autor';
        END IF;
    END
$$;


-- Libros a corregir.
DROP TABLE IF EXISTS pg_temp.s17_target_books;

CREATE TEMP TABLE s17_target_books
(
    isbn VARCHAR(20) PRIMARY KEY
) ON COMMIT DROP;

INSERT INTO s17_target_books (isbn)
VALUES ('9788446032304'), -- COMMONWEALTH
       ('9788446047599'); -- ASAMBLEA


DROP TABLE IF EXISTS pg_temp.s17_resolved_books;

CREATE TEMP TABLE s17_resolved_books ON COMMIT DROP AS
SELECT tb.isbn,
       b.id AS book_id,
       b.title
FROM s17_target_books tb
         JOIN books b
              ON b.isbn_13 = tb.isbn
                  OR b.isbn_10 = tb.isbn;



DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s17_target_books tb
                            LEFT JOIN books b
                                      ON b.isbn_13 = tb.isbn
                                          OR b.isbn_10 = tb.isbn
                   GROUP BY tb.isbn
                   HAVING COUNT(DISTINCT b.id) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: algún libro no resuelve exactamente por ISBN';
        END IF;
    END
$$;


-- Agregar Hardt y Negri a ambos libros.
INSERT INTO book_authors (book_id, author_id)
SELECT rb.book_id,
       ra.author_id
FROM s17_resolved_books rb
         CROSS JOIN s17_resolved_authors ra
ON CONFLICT (book_id, author_id) DO NOTHING;


-- Retirar las autorías concatenadas.
DELETE
FROM book_authors ba
    USING authors a, s17_resolved_books rb
WHERE ba.author_id = a.id
  AND ba.book_id = rb.book_id
  AND a.name_normalized IN (
                            'hardt negri',
                            'hardt negri y otros'
    );


-- Eliminar autores concatenados si quedaron huérfanos.
DELETE
FROM authors a
WHERE a.name_normalized IN (
                            'hardt negri',
                            'hardt negri y otros',
                            'negri hardt'
    )
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);



