-- Resolver el libro por ISBN.
WITH target_book AS (SELECT id
                     FROM books
                     WHERE isbn_13 = '9789878450155'
                        OR isbn_10 = '9789878450155'),
     target_author AS (SELECT id
                       FROM authors
                       WHERE name_normalized = 'garcia blanco hector')
INSERT
INTO book_authors (book_id, author_id)
SELECT tb.id, ta.id
FROM target_book tb
         CROSS JOIN target_author ta
ON CONFLICT (book_id, author_id) DO NOTHING;

-- Quitar el autor compuesto.
DELETE
FROM book_authors ba
    USING books b, authors a
WHERE ba.book_id = b.id
  AND ba.author_id = a.id
  AND (b.isbn_13 = '9789878450155' OR b.isbn_10 = '9789878450155')
  AND a.name_normalized IN (
                            'blanco garcia',
                            'garcia blanco'
    );

-- Eliminar esas variantes si quedaron huérfanas.
DELETE
FROM authors a
WHERE a.name_normalized IN (
                            'blanco garcia',
                            'garcia blanco'
    )
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);



