DROP TABLE IF EXISTS pg_temp.s19_author_merge_rules;
CREATE TEMP TABLE s19_author_merge_rules
(
    canonical_name_normalized VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    PRIMARY KEY (duplicate_name_normalized),
    CHECK (canonical_name_normalized <> duplicate_name_normalized)
) ON COMMIT DROP;

INSERT INTO s19_author_merge_rules (canonical_name_normalized,
                                    duplicate_name_normalized)
VALUES ('alejandro sharp vergara', 'vergara sharp alejandro'),
       ('angel miguel navarro', 'navarro miguel angel'),
       ('cecilia maria galindo', 'galindo maria cecilia'),
       ('enrique valdecantos diaz', 'diaz valdecantos enrique'),
       ('galo casado sanchez', 'sanchez casado galo'),
       ('javier fernandez aguado', 'aguado fernandez javier'),
       ('jazmin naida ochoa', 'ochoa naida jazmin'),
       ('lucio apuleyo', 'apuleyo lucio'),
       ('miguel hernandez jimenez', 'jimenez hernandez miguel'),
       ('nicolas campos farfan', 'farfan campos nicolas'),
       ('pierre jean amar', 'amar jean pierre'),
       ('silvia baron supervielle', 'supervielle baron silvia'),
       ('sixto wells paz', 'paz wells sixto');

DO
$$
    BEGIN
        IF EXISTS (WITH resolved AS (SELECT r.canonical_name_normalized,
                                            r.duplicate_name_normalized,
                                            COUNT(DISTINCT c.id) AS canonical_matches,
                                            COUNT(DISTINCT d.id) AS duplicate_matches
                                     FROM s19_author_merge_rules r
                                              LEFT JOIN authors c ON c.name_normalized = r.canonical_name_normalized
                                              LEFT JOIN authors d ON d.name_normalized = r.duplicate_name_normalized
                                     GROUP BY r.canonical_name_normalized, r.duplicate_name_normalized)
                   SELECT 1
                   FROM resolved
                   WHERE canonical_matches <> 1
                      OR duplicate_matches > 1) THEN
            RAISE EXCEPTION 'Abortado: alguna regla no tiene un destino único o la fuente es ambigua';
        END IF;
    END
$$;

DROP TABLE IF EXISTS pg_temp.s19_author_merges;
CREATE TEMP TABLE s19_author_merges ON COMMIT DROP AS
SELECT c.id   AS canonical_id,
       d.id   AS duplicate_id,
       c.name AS canonical_name,
       d.name AS duplicate_name
FROM s19_author_merge_rules r
         JOIN authors c ON c.name_normalized = r.canonical_name_normalized
         JOIN authors d ON d.name_normalized = r.duplicate_name_normalized;



INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id, am.canonical_id
FROM s19_author_merges am
         JOIN book_authors ba ON ba.author_id = am.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;

DELETE
FROM book_authors ba
    USING s19_author_merges am
WHERE ba.author_id = am.duplicate_id;

DELETE
FROM authors a
    USING s19_author_merges am
WHERE a.id = am.duplicate_id;



