-- Cada variante puede resolver como máximo una vez.
-- Al menos una de las dos debe existir.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s20_author_merge_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.canonical_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.duplicate_name_normalized) > 1
                      OR NOT EXISTS (SELECT 1
                                     FROM authors a
                                     WHERE a.name_normalized IN (
                                                                 r.canonical_name_normalized,
                                                                 r.duplicate_name_normalized
                                         ))) THEN
            RAISE EXCEPTION
                'V69/Script-20: alguna regla no encuentra un autor resoluble o es ambigua';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s20_author_merges;

CREATE TEMP TABLE s20_author_merges
(
    canonical_name_normalized VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    canonical_id              BIGINT       NOT NULL,
    original_canonical_id     BIGINT,
    duplicate_id              BIGINT
) ON COMMIT DROP;


INSERT INTO s20_author_merges (canonical_name_normalized,
                               duplicate_name_normalized,
                               canonical_id,
                               original_canonical_id,
                               duplicate_id)
SELECT r.canonical_name_normalized,
       r.duplicate_name_normalized,
       COALESCE(c.id, d.id) AS canonical_id,
       c.id                 AS original_canonical_id,
       d.id                 AS duplicate_id
FROM s20_author_merge_rules r
         LEFT JOIN authors c
                   ON c.name_normalized = r.canonical_name_normalized
         LEFT JOIN authors d
                   ON d.name_normalized = r.duplicate_name_normalized;


-- Si existen ambos registros, mover las relaciones del duplicado
-- hacia el registro que conservamos.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                am.canonical_id
FROM s20_author_merges am
         JOIN book_authors ba
              ON ba.author_id = am.duplicate_id
WHERE am.duplicate_id IS NOT NULL
  AND am.duplicate_id <> am.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


-- Eliminar las relaciones del duplicado absorbido.
DELETE
FROM book_authors ba
    USING s20_author_merges am
WHERE am.duplicate_id IS NOT NULL
  AND am.duplicate_id <> am.canonical_id
  AND ba.author_id = am.duplicate_id;


-- Eliminar el registro duplicado absorbido.
DELETE
FROM authors a
    USING s20_author_merges am
WHERE am.duplicate_id IS NOT NULL
  AND am.duplicate_id <> am.canonical_id
  AND a.id = am.duplicate_id;


-- Si sólo existía el nombre invertido, ese mismo ID pasa a ser el canónico.
-- Si ya existía el canónico, esto simplemente reafirma su nombre normalizado.
UPDATE authors a
SET name_normalized = am.canonical_name_normalized
FROM s20_author_merges am
WHERE a.id = am.canonical_id
  AND a.name_normalized IS DISTINCT FROM am.canonical_name_normalized;


-- Postcondición:
-- cada regla debe terminar exactamente con un autor canónico
-- y ninguna variante invertida debe permanecer.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s20_author_merge_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.canonical_name_normalized) <> 1) THEN
            RAISE EXCEPTION
                'V69/Script-20: alguna regla no terminó con exactamente un autor canónico';
        END IF;

        IF EXISTS (SELECT 1
                   FROM s20_author_merge_rules r
                            JOIN authors a
                                 ON a.name_normalized = r.duplicate_name_normalized) THEN
            RAISE EXCEPTION
                'V69/Script-20: quedó alguna variante invertida sin consolidar';
        END IF;
    END
$$;


