DO
$$
    BEGIN
        IF EXISTS (WITH resolved AS (SELECT r.canonical_name_normalized,
                                            r.duplicate_name_normalized,
                                            COUNT(DISTINCT c.id) AS canonical_matches,
                                            COUNT(DISTINCT d.id) AS duplicate_matches
                                     FROM s21_author_merge_rules r
                                              LEFT JOIN authors c ON c.name_normalized = r.canonical_name_normalized
                                              LEFT JOIN authors d ON d.name_normalized = r.duplicate_name_normalized
                                     GROUP BY r.canonical_name_normalized, r.duplicate_name_normalized)
                   SELECT 1
                   FROM resolved
                   WHERE canonical_matches <> 1
                      OR duplicate_matches > 1) THEN
            RAISE EXCEPTION 'Abortado: alguna regla no tiene un destino único o la fuente es ambigua';
        END IF;
    END
$$;

DROP TABLE IF EXISTS pg_temp.s21_author_merges;
CREATE TEMP TABLE s21_author_merges ON COMMIT DROP AS
SELECT c.id   AS canonical_id,
       d.id   AS duplicate_id,
       c.name AS canonical_name,
       d.name AS duplicate_name
FROM s21_author_merge_rules r
         JOIN authors c ON c.name_normalized = r.canonical_name_normalized
         JOIN authors d ON d.name_normalized = r.duplicate_name_normalized;



INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id, am.canonical_id
FROM s21_author_merges am
         JOIN book_authors ba ON ba.author_id = am.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;

DELETE
FROM book_authors ba
    USING s21_author_merges am
WHERE ba.author_id = am.duplicate_id;

DELETE
FROM authors a
    USING s21_author_merges am
WHERE a.id = am.duplicate_id;

