DROP TABLE IF EXISTS pg_temp.s22_author_merges;
CREATE TEMP TABLE s22_author_merges ON COMMIT DROP AS
SELECT c.id   AS canonical_id,
       d.id   AS duplicate_id,
       c.name AS canonical_name,
       d.name AS duplicate_name
FROM s22_author_merge_rules r
