-- =========================================================
-- A) AUTORES INDIVIDUALES
-- =========================================================

DROP TABLE IF EXISTS pg_temp.s26_individual_author_rules;

CREATE TEMP TABLE s26_individual_author_rules
(
    current_name_normalized   VARCHAR(255) NOT NULL PRIMARY KEY,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    final_name                VARCHAR(255) NOT NULL,
    final_name_normalized     VARCHAR(255) NOT NULL,
    CHECK (current_name_normalized <> duplicate_name_normalized)
) ON COMMIT DROP;

INSERT INTO s26_individual_author_rules (current_name_normalized,
                                         duplicate_name_normalized,
                                         final_name,
                                         final_name_normalized)
VALUES ('de rosa alabaster enrique', 'alabaster enrique de rosa',
        'Enrique De Rosa Alabaster', 'enrique de rosa alabaster'),

       ('galan silvia ana', 'galan ana silvia',
        'Ana Silvia Galán', 'ana silvia galan'),

       ('diaz maria ana', 'diaz ana maria',
        'Ana María Díaz', 'ana maria diaz'),

       ('fragola ortiz a', 'ortiz fragola a',
        'Alfredo Ortiz Frágola', 'alfredo ortiz fragola'),

       ('edgar allan garcia', 'allan garcia edgar',
        'Edgar Allan García', 'edgar allan garcia'),

       ('frayle elena alonso', 'alonso frayle elena',
        'Elena Alonso Frayle', 'elena alonso frayle'),

       ('murcio maghei amalia', 'maghei amalia murcio',
        'Amalia Murcio Maghei', 'amalia murcio maghei'),

       ('adam tania safura', 'tania safura adam',
        'Tania Safura Adam', 'tania safura adam');


-- Cada uno de los nombres posibles debe resolver como máximo a un autor.
-- Las fuentes pueden no existir porque el lote pudo haberse ejecutado antes.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s26_individual_author_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.current_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.duplicate_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla individual resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s26_individual_author_merges;

CREATE TEMP TABLE s26_individual_author_merges
(
    current_name_normalized   VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    final_name                VARCHAR(255) NOT NULL,
    final_name_normalized     VARCHAR(255) NOT NULL,
    canonical_id              BIGINT,
    current_id                BIGINT,
    duplicate_id              BIGINT,
    final_id                  BIGINT
) ON COMMIT DROP;


INSERT INTO s26_individual_author_merges (current_name_normalized,
                                          duplicate_name_normalized,
                                          final_name,
                                          final_name_normalized,
                                          canonical_id,
                                          current_id,
                                          duplicate_id,
                                          final_id)
SELECT r.current_name_normalized,
       r.duplicate_name_normalized,
       r.final_name,
       r.final_name_normalized,
       COALESCE(f.id, c.id, d.id) AS canonical_id,
       c.id                       AS current_id,
       d.id                       AS duplicate_id,
       f.id                       AS final_id
FROM s26_individual_author_rules r
         LEFT JOIN authors c
                   ON c.name_normalized = r.current_name_normalized
         LEFT JOIN authors d
                   ON d.name_normalized = r.duplicate_name_normalized
         LEFT JOIN authors f
                   ON f.name_normalized = r.final_name_normalized;


-- Mover al canónico todas las relaciones pertenecientes a otros registros
-- que representen cualquiera de los nombres de la regla.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                iam.canonical_id
FROM s26_individual_author_merges iam
         JOIN book_authors ba
              ON ba.author_id IN (
                                  iam.current_id,
                                  iam.duplicate_id,
                                  iam.final_id
                  )
WHERE iam.canonical_id IS NOT NULL
  AND ba.author_id <> iam.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


-- Eliminar relaciones de los registros que serán absorbidos.
DELETE
FROM book_authors ba
    USING s26_individual_author_merges iam
WHERE iam.canonical_id IS NOT NULL
  AND ba.author_id IN (
                       iam.current_id,
                       iam.duplicate_id,
                       iam.final_id
    )
  AND ba.author_id <> iam.canonical_id;


-- Eliminar registros absorbidos.
DELETE
FROM authors a
    USING s26_individual_author_merges iam
WHERE iam.canonical_id IS NOT NULL
  AND a.id IN (
               iam.current_id,
               iam.duplicate_id,
               iam.final_id
    )
  AND a.id <> iam.canonical_id;


-- Llevar siempre el registro conservado al nombre final.
UPDATE authors a
SET name            = iam.final_name,
    name_normalized = iam.final_name_normalized
FROM s26_individual_author_merges iam
WHERE a.id = iam.canonical_id
  AND (
    a.name IS DISTINCT FROM iam.final_name
        OR a.name_normalized IS DISTINCT FROM iam.final_name_normalized
    );


-- Postcondición:
-- ninguno de los nombres históricos diferentes del nombre final
-- debe seguir existiendo.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s26_individual_author_rules r
                            JOIN authors a
                                 ON a.name_normalized IN (
                                                          r.current_name_normalized,
                                                          r.duplicate_name_normalized
                                     )
                   WHERE a.name_normalized <> r.final_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron autores individuales históricos sin consolidar';
        END IF;
    END
$$;


-- =========================================================
-- A.2) JACQUES-ALAIN MILLER: 3 -> 1
-- =========================================================

DROP TABLE IF EXISTS pg_temp.s26_miller_merge_sources;

