DO
$$
    BEGIN
        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'jacques alain miller') <> 1 THEN
            RAISE EXCEPTION
                'Abortado: Jacques-Alain Miller canónico no resuelve exactamente una vez';
        END IF;

        IF EXISTS (SELECT 1
                   FROM s26_miller_merge_sources m
                            LEFT JOIN authors a
                                      ON a.name_normalized = m.duplicate_name_normalized
                   GROUP BY m.duplicate_name_normalized
                   HAVING COUNT(a.id) > 1) THEN
            RAISE EXCEPTION
                'Abortado: algún duplicado de Jacques-Alain Miller no resuelve exactamente una vez';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s26_miller_merges;

