SELECT canonical.id   AS canonical_id,
       canonical.name AS canonical_name,
       duplicate.id   AS duplicate_id,
       duplicate.name AS duplicate_name
FROM authors canonical
         CROSS JOIN s26_miller_merge_sources m
         JOIN authors duplicate
              ON duplicate.name_normalized = m.duplicate_name_normalized
WHERE canonical.name_normalized = 'jacques alain miller';



INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id,
       mm.canonical_id
FROM s26_miller_merges mm
         JOIN book_authors ba
              ON ba.author_id = mm.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s26_miller_merges mm
WHERE ba.author_id = mm.duplicate_id;


DELETE
FROM authors a
    USING s26_miller_merges mm
WHERE a.id = mm.duplicate_id;


