-- Resolver los 3 libros por ISBN.
DROP TABLE IF EXISTS pg_temp.s26_coauthor_target_books;

CREATE TEMP TABLE s26_coauthor_target_books ON COMMIT DROP AS
SELECT DISTINCT r.isbn,
                b.id AS book_id,
                b.title
FROM s26_coauthor_book_rules r
         JOIN books b
              ON b.isbn_13 = r.isbn
                  OR b.isbn_10 = r.isbn;



DO
$$
    BEGIN
        IF (SELECT COUNT(DISTINCT isbn)
            FROM s26_coauthor_target_books) <> 3 THEN
            RAISE EXCEPTION
                'Abortado: no se resolvieron exactamente los 3 ISBN esperados';
        END IF;
    END
$$;



DO
$$
    BEGIN
        IF EXISTS (WITH source_rules AS (SELECT DISTINCT source_author_name_normalized
                                         FROM s26_coauthor_book_rules),
                        source_resolution AS (SELECT sr.source_author_name_normalized,
                                                     COUNT(a.id) AS matches
                                              FROM source_rules sr
                                                       LEFT JOIN authors a
                                                                 ON a.name_normalized = sr.source_author_name_normalized
                                              GROUP BY sr.source_author_name_normalized)
                   SELECT 1
                   FROM source_resolution
                   WHERE matches > 1) THEN
            RAISE EXCEPTION
                'Abortado: algún autor concatenado fuente no resuelve exactamente una vez';
        END IF;
    END
$$;


