-- Matías Alinovi puede encontrarse:
-- - todavía invertido como "alinovi matias"
-- - ya normalizado como "matias alinovi"
-- - en ambos estados por una limpieza parcial
-- La migración debe consolidar todo en un único autor final.

DO
$$
    BEGIN
        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'alinovi matias') > 1 THEN
            RAISE EXCEPTION
                'Abortado: alinovi matias resuelve ambiguamente';
        END IF;

        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'matias alinovi') > 1 THEN
            RAISE EXCEPTION
                'Abortado: matias alinovi resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s26_matias_alinovi_merge;

CREATE TEMP TABLE s26_matias_alinovi_merge
(
    canonical_id BIGINT,
    source_id    BIGINT
) ON COMMIT DROP;


INSERT INTO s26_matias_alinovi_merge (canonical_id, source_id)
SELECT COALESCE(final_author.id, source_author.id),
       source_author.id
FROM (SELECT 1) x
         LEFT JOIN authors final_author
                   ON final_author.name_normalized = 'matias alinovi'
         LEFT JOIN authors source_author
                   ON source_author.name_normalized = 'alinovi matias';


-- Si existen ambos registros, mover las relaciones del invertido al final.
INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id,
       m.canonical_id
FROM s26_matias_alinovi_merge m
         JOIN book_authors ba
              ON ba.author_id = m.source_id
WHERE m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s26_matias_alinovi_merge m
WHERE ba.author_id = m.source_id
  AND m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id;


DELETE
FROM authors a
    USING s26_matias_alinovi_merge m
WHERE a.id = m.source_id
  AND m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id;


-- Si sólo existía el invertido, convertirlo al estado final.
UPDATE authors a
SET name            = 'Matías Alinovi',
    name_normalized = 'matias alinovi'
FROM s26_matias_alinovi_merge m
WHERE a.id = m.canonical_id
  AND (
    a.name IS DISTINCT FROM 'Matías Alinovi'
        OR a.name_normalized IS DISTINCT FROM 'matias alinovi'
    );


-- Diego Alterleib puede encontrarse:
-- - todavía invertido como "alterleib diego"
-- - ya normalizado como "diego alterleib"
-- - en ambos estados por una limpieza parcial
-- La migración debe consolidar todo en un único autor final.

DO
$$
    BEGIN
        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'alterleib diego') > 1 THEN
            RAISE EXCEPTION
                'Abortado: alterleib diego resuelve ambiguamente';
        END IF;

        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'diego alterleib') > 1 THEN
            RAISE EXCEPTION
                'Abortado: diego alterleib resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s26_diego_alterleib_merge;

CREATE TEMP TABLE s26_diego_alterleib_merge
(
    canonical_id BIGINT,
    source_id    BIGINT
) ON COMMIT DROP;


INSERT INTO s26_diego_alterleib_merge (canonical_id, source_id)
SELECT COALESCE(final_author.id, source_author.id),
       source_author.id
FROM (SELECT 1) x
         LEFT JOIN authors final_author
                   ON final_author.name_normalized = 'diego alterleib'
         LEFT JOIN authors source_author
                   ON source_author.name_normalized = 'alterleib diego';


-- Si existen ambos registros, mover las relaciones del invertido al final.
INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id,
       m.canonical_id
FROM s26_diego_alterleib_merge m
         JOIN book_authors ba
              ON ba.author_id = m.source_id
WHERE m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s26_diego_alterleib_merge m
WHERE ba.author_id = m.source_id
  AND m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id;


DELETE
FROM authors a
    USING s26_diego_alterleib_merge m
WHERE a.id = m.source_id
  AND m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id;


-- Si sólo existía el invertido, convertirlo al estado final.
UPDATE authors a
SET name            = 'Diego Alterleib',
    name_normalized = 'diego alterleib'
FROM s26_diego_alterleib_merge m
WHERE a.id = m.canonical_id
  AND (
    a.name IS DISTINCT FROM 'Diego Alterleib'
        OR a.name_normalized IS DISTINCT FROM 'diego alterleib'
    );


-- Postcondición: no debe quedar el nombre histórico invertido.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM authors
                   WHERE name_normalized = 'alterleib diego') THEN
            RAISE EXCEPTION
                'Abortado: quedó el autor histórico alterleib diego sin normalizar';
        END IF;
    END
$$;


-- Validar que los siete autores objetivo existan exactamente una vez.
DROP TABLE IF EXISTS pg_temp.s26_coauthor_targets;

CREATE TEMP TABLE s26_coauthor_targets
(
    target_key             VARCHAR(64) PRIMARY KEY,
    target_name_normalized VARCHAR(255) NOT NULL
) ON COMMIT DROP;

INSERT INTO s26_coauthor_targets (target_key, target_name_normalized)
VALUES ('RUTH_KAUFMAN', 'ruth kaufman'),
       ('CRISTINA_MORAS', 'cristina moras'),
       ('PABLO_ALARCON_ELIAS', 'pablo alarcon elias'),
       ('RICARDO_ALCANTARA', 'ricardo alcantara'),
       ('GUSTI', 'gusti'),
       ('MATIAS_ALINOVI', 'matias alinovi'),
       ('DIEGO_ALTERLEIB', 'diego alterleib');



DO
$$
    BEGIN
        IF EXISTS (WITH target_resolution AS (SELECT t.target_key,
                                                     t.target_name_normalized,
                                                     COUNT(a.id) AS matches
                                              FROM s26_coauthor_targets t
                                                       LEFT JOIN authors a
                                                                 ON a.name_normalized = t.target_name_normalized
                                              GROUP BY t.target_key,
                                                       t.target_name_normalized)
                   SELECT 1
                   FROM target_resolution
                   WHERE matches <> 1) THEN
            RAISE EXCEPTION
                'Abortado: algún coautor individual no existe exactamente una vez';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s26_resolved_coauthor_rules;

CREATE TEMP TABLE s26_resolved_coauthor_rules ON COMMIT DROP AS
SELECT b.id        AS book_id,
       b.title,
       r.isbn,
       source.id   AS source_author_id,
       source.name AS source_author_name,
       target.id   AS target_author_id,
       target.name AS target_author_name
FROM s26_coauthor_book_rules r
         JOIN books b
              ON b.isbn_13 = r.isbn
                  OR b.isbn_10 = r.isbn
         JOIN authors source
              ON source.name_normalized = r.source_author_name_normalized
         JOIN s26_coauthor_targets t
              ON t.target_key = r.target_key
         JOIN authors target
              ON target.name_normalized = t.target_name_normalized;


-- Agregar los autores individuales.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT book_id,
                target_author_id
FROM s26_resolved_coauthor_rules
ON CONFLICT (book_id, author_id) DO NOTHING;


-- Quitar el registro concatenado únicamente de esos libros.
DELETE
FROM book_authors ba
    USING (SELECT DISTINCT book_id,
                           source_author_id
           FROM s26_resolved_coauthor_rules) x
WHERE ba.book_id = x.book_id
  AND ba.author_id = x.source_author_id;


-- Eliminar los autores concatenados si quedaron huérfanos.
DELETE
FROM authors a
WHERE a.id IN (SELECT DISTINCT source_author_id
               FROM s26_resolved_coauthor_rules)
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);



