) ON COMMIT DROP;


INSERT INTO s28_individual_author_merges (current_name_normalized,
                                          duplicate_name_normalized,
                                          final_name,
                                          final_name_normalized,
                                          canonical_id,
                                          current_id,
                                          duplicate_id,
                                          final_id)
SELECT r.current_name_normalized,
       r.duplicate_name_normalized,
       r.final_name,
       r.final_name_normalized,
       COALESCE(f.id, c.id, d.id),
       c.id,
       d.id,
       f.id
FROM s28_individual_author_rules r
         LEFT JOIN authors c
                   ON c.name_normalized = r.current_name_normalized
         LEFT JOIN authors d
                   ON d.name_normalized = r.duplicate_name_normalized
         LEFT JOIN authors f
                   ON f.name_normalized = r.final_name_normalized;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s28_individual_author_merges
                   WHERE canonical_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla individual de Script-28 no encuentra ningún autor candidato';
        END IF;
    END
$$;


INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                iam.canonical_id
FROM s28_individual_author_merges iam
         JOIN book_authors ba
              ON ba.author_id IN (
                                  iam.current_id,
                                  iam.duplicate_id,
                                  iam.final_id
                  )
WHERE iam.canonical_id IS NOT NULL
  AND ba.author_id <> iam.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s28_individual_author_merges iam
WHERE iam.canonical_id IS NOT NULL
  AND ba.author_id IN (
                       iam.current_id,
                       iam.duplicate_id,
                       iam.final_id
    )
  AND ba.author_id <> iam.canonical_id;


DELETE
FROM authors a
    USING s28_individual_author_merges iam
WHERE iam.canonical_id IS NOT NULL
  AND a.id IN (
               iam.current_id,
               iam.duplicate_id,
               iam.final_id
    )
  AND a.id <> iam.canonical_id;


UPDATE authors a
SET name            = iam.final_name,
    name_normalized = iam.final_name_normalized
FROM s28_individual_author_merges iam
WHERE a.id = iam.canonical_id
  AND (
    a.name IS DISTINCT FROM iam.final_name
        OR a.name_normalized IS DISTINCT FROM iam.final_name_normalized
    );


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s28_individual_author_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla individual de Script-28 no terminó con exactamente un autor final';
        END IF;

        IF EXISTS (SELECT 1
                   FROM s28_individual_author_rules r
                            JOIN authors a
                                 ON a.name_normalized IN (
                                                          r.current_name_normalized,
                                                          r.duplicate_name_normalized
                                     )
                   WHERE a.name_normalized <> r.final_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron variantes históricas individuales sin consolidar en Script-28';
        END IF;
    END
$$;


-- =========================================================
-- B) PREPARAR AUTORES INDIVIDUALES DE COAUTORÍAS
-- =========================================================

-- César Bandin Ron puede encontrarse:
-- - todavía invertido como "bandin ron cesar"
-- - ya normalizado como "cesar bandin ron"
-- - en ambos estados por una limpieza parcial
-- La migración debe consolidar todo en un único autor final.

DO
$$
    BEGIN
        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'bandin ron cesar') > 1 THEN
            RAISE EXCEPTION
                'Abortado: bandin ron cesar resuelve ambiguamente';
        END IF;

        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'cesar bandin ron') > 1 THEN
            RAISE EXCEPTION
                'Abortado: cesar bandin ron resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s28_cesar_bandin_ron_merge;

CREATE TEMP TABLE s28_cesar_bandin_ron_merge
(
    canonical_id BIGINT,
    source_id    BIGINT
) ON COMMIT DROP;


INSERT INTO s28_cesar_bandin_ron_merge (canonical_id, source_id)
SELECT COALESCE(final_author.id, source_author.id),
       source_author.id
FROM (SELECT 1) x
         LEFT JOIN authors final_author
                   ON final_author.name_normalized = 'cesar bandin ron'
         LEFT JOIN authors source_author
                   ON source_author.name_normalized = 'bandin ron cesar';


INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id,
       m.canonical_id
FROM s28_cesar_bandin_ron_merge m
         JOIN book_authors ba
              ON ba.author_id = m.source_id
WHERE m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s28_cesar_bandin_ron_merge m
WHERE ba.author_id = m.source_id
  AND m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id;


DELETE
FROM authors a
    USING s28_cesar_bandin_ron_merge m
WHERE a.id = m.source_id
  AND m.canonical_id IS NOT NULL
  AND m.source_id IS NOT NULL
  AND m.source_id <> m.canonical_id;


UPDATE authors a
SET name            = 'César Bandin Ron',
    name_normalized = 'cesar bandin ron'
FROM s28_cesar_bandin_ron_merge m
WHERE a.id = m.canonical_id
  AND (
    a.name IS DISTINCT FROM 'César Bandin Ron'
        OR a.name_normalized IS DISTINCT FROM 'cesar bandin ron'
    );


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM authors
                   WHERE name_normalized = 'bandin ron cesar') THEN
            RAISE EXCEPTION
                'Abortado: quedó el autor histórico bandin ron cesar sin normalizar';
        END IF;
    END
$$;


-- Aya Koda existe como KODA AYA y además hay una variante vacía AYA, KODA.
-- Conservamos el registro usado.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM authors
                   WHERE name_normalized = 'aya koda'
                     AND name_normalized <> 'koda aya') THEN
            NULL;
        END IF;
    END
$$;

-- Eliminar primero la variante vacía, si efectivamente está vacía.
DELETE
FROM authors a
WHERE a.name_normalized = 'aya koda'
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);

UPDATE authors
SET name            = 'Aya Koda',
    name_normalized = 'aya koda'
WHERE name_normalized = 'koda aya';


