                                    FROM s28_coauthor_rules),
                        source_resolution AS (SELECT s.source_name_normalized,
                                                     COUNT(a.id) AS matches
                                              FROM sources s
                                                       LEFT JOIN authors a
                                                                 ON a.name_normalized = s.source_name_normalized
                                              GROUP BY s.source_name_normalized)
                   SELECT 1
                   FROM source_resolution
                   WHERE matches > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna fuente concatenada de Script-28 resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s28_resolved_coauthor_rules;

CREATE TEMP TABLE s28_resolved_coauthor_rules ON COMMIT DROP AS
SELECT source.id   AS source_author_id,
       source.name AS source_author_name,
       target.id   AS target_author_id,
       target.name AS target_author_name
FROM s28_coauthor_rules r
         JOIN authors source
              ON source.name_normalized = r.source_name_normalized
         JOIN authors target
              ON target.name_normalized = r.target_name_normalized;


-- Guardar todos los libros afectados antes de modificar relaciones.
DROP TABLE IF EXISTS pg_temp.s28_coauthor_affected_books;

CREATE TEMP TABLE s28_coauthor_affected_books ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                r.source_author_id
FROM s28_resolved_coauthor_rules r
         JOIN book_authors ba
              ON ba.author_id = r.source_author_id;


-- Agregar autores individuales a todos los libros de cada fuente.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                r.target_author_id
FROM s28_resolved_coauthor_rules r
         JOIN book_authors ba
              ON ba.author_id = r.source_author_id
ON CONFLICT (book_id, author_id) DO NOTHING;


-- Quitar las relaciones de autores concatenados.
DELETE
FROM book_authors ba
    USING s28_coauthor_affected_books x
WHERE ba.book_id = x.book_id
  AND ba.author_id = x.source_author_id;


-- Eliminar las fuentes concatenadas si quedaron huérfanas.
DELETE
FROM authors a
WHERE a.id IN (SELECT DISTINCT source_author_id
               FROM s28_resolved_coauthor_rules)
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);


