-- =========================================================
-- A) RESOLVER AUTORES INDIVIDUALES DE FORMA IDEMPOTENTE
-- =========================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s30_individual_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.source_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE r.duplicate_name_normalized IS NOT NULL
                            AND a.name_normalized = r.duplicate_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla individual de Script-30 resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s30_individual_merge_plan;

CREATE TEMP TABLE s30_individual_merge_plan
(
    source_name_normalized    VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255),
    final_name                VARCHAR(255) NOT NULL,
    final_name_normalized     VARCHAR(255) NOT NULL,
    canonical_id              BIGINT,
    source_id                 BIGINT,
    duplicate_id              BIGINT,
    final_id                  BIGINT
) ON COMMIT DROP;


INSERT INTO s30_individual_merge_plan (source_name_normalized,
                                       duplicate_name_normalized,
                                       final_name,
                                       final_name_normalized,
                                       canonical_id,
                                       source_id,
                                       duplicate_id,
                                       final_id)
SELECT r.source_name_normalized,
       r.duplicate_name_normalized,
       r.final_name,
       r.final_name_normalized,
       COALESCE(f.id, s.id, d.id),
       s.id,
       d.id,
       f.id
FROM s30_individual_rules r
         LEFT JOIN authors s
                   ON s.name_normalized = r.source_name_normalized
         LEFT JOIN authors d
                   ON r.duplicate_name_normalized IS NOT NULL
                       AND d.name_normalized = r.duplicate_name_normalized
         LEFT JOIN authors f
                   ON f.name_normalized = r.final_name_normalized;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s30_individual_merge_plan
                   WHERE canonical_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla individual de Script-30 no encuentra ningún autor candidato';
        END IF;
    END
$$;


-- Mover al canónico las relaciones de cualquier otro registro
-- perteneciente a la misma regla.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                p.canonical_id
FROM s30_individual_merge_plan p
         JOIN book_authors ba
              ON ba.author_id IN (
                                  p.source_id,
                                  p.duplicate_id,
                                  p.final_id
                  )
WHERE p.canonical_id IS NOT NULL
  AND ba.author_id <> p.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


-- Eliminar las relaciones de los registros absorbidos.
DELETE
FROM book_authors ba
    USING s30_individual_merge_plan p
WHERE p.canonical_id IS NOT NULL
  AND ba.author_id IN (
                       p.source_id,
                       p.duplicate_id,
                       p.final_id
    )
  AND ba.author_id <> p.canonical_id;


-- Eliminar los autores absorbidos.
DELETE
FROM authors a
    USING s30_individual_merge_plan p
WHERE p.canonical_id IS NOT NULL
  AND a.id IN (
               p.source_id,
               p.duplicate_id,
               p.final_id
    )
  AND a.id <> p.canonical_id;


-- Llevar siempre el registro conservado al nombre final.
UPDATE authors a
SET name            = p.final_name,
    name_normalized = p.final_name_normalized
FROM s30_individual_merge_plan p
WHERE a.id = p.canonical_id
  AND (
    a.name IS DISTINCT FROM p.final_name
        OR a.name_normalized IS DISTINCT FROM p.final_name_normalized
    );


-- Postcondiciones.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s30_individual_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla individual de Script-30 no terminó con exactamente un autor final';
        END IF;

        IF EXISTS (SELECT 1
                   FROM s30_individual_rules r
                            JOIN authors a
                                 ON a.name_normalized = r.source_name_normalized
                                     OR (
                                        r.duplicate_name_normalized IS NOT NULL
                                            AND a.name_normalized = r.duplicate_name_normalized
                                        )
                   WHERE a.name_normalized <> r.final_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron variantes históricas individuales sin consolidar en Script-30';
        END IF;
    END
$$;

