       ('pujol caut', 'vincent caut');



DO
$$
    BEGIN
        IF EXISTS (WITH sources AS (SELECT DISTINCT source_name_normalized
                                    FROM s30_coauthor_rules),
                        resolution AS (SELECT s.source_name_normalized,
                                              COUNT(a.id) AS matches
                                       FROM sources s
                                                LEFT JOIN authors a
                                                          ON a.name_normalized = s.source_name_normalized
                                       GROUP BY s.source_name_normalized)
                   SELECT 1
                   FROM resolution
                   WHERE matches > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna fuente concatenada de Script-30 resuelve ambiguamente';
        END IF;
    END
$$;



DO
$$
    BEGIN
        IF EXISTS (WITH targets AS (SELECT DISTINCT target_name_normalized
                                    FROM s30_coauthor_rules),
                        resolution AS (SELECT t.target_name_normalized,
                                              COUNT(a.id) AS matches
                                       FROM targets t
                                                LEFT JOIN authors a
                                                          ON a.name_normalized = t.target_name_normalized
                                       GROUP BY t.target_name_normalized)
                   SELECT 1
                   FROM resolution
                   WHERE matches <> 1) THEN
            RAISE EXCEPTION
                'Abortado: algún coautor objetivo no resuelve exactamente una vez';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s30_resolved_coauthors;

CREATE TEMP TABLE s30_resolved_coauthors ON COMMIT DROP AS
SELECT s.id   AS source_author_id,
       s.name AS source_author_name,
       t.id   AS target_author_id,
       t.name AS target_author_name
FROM s30_coauthor_rules r
         JOIN authors s
              ON s.name_normalized = r.source_name_normalized
         JOIN authors t
              ON t.name_normalized = r.target_name_normalized;



DROP TABLE IF EXISTS pg_temp.s30_affected_books;

CREATE TEMP TABLE s30_affected_books ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.source_author_id
FROM s30_resolved_coauthors rc
         JOIN book_authors ba
              ON ba.author_id = rc.source_author_id;


INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                rc.target_author_id
FROM s30_resolved_coauthors rc
         JOIN book_authors ba
              ON ba.author_id = rc.source_author_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s30_affected_books ab
WHERE ba.book_id = ab.book_id
  AND ba.author_id = ab.source_author_id;


DELETE
FROM authors a
WHERE a.id IN (SELECT DISTINCT source_author_id
               FROM s30_resolved_coauthors)
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);


