DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s31_author_merge_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.current_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.duplicate_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla de Script-31 resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s31_author_merges;

CREATE TEMP TABLE s31_author_merges
(
    current_name_normalized   VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    final_name                VARCHAR(255) NOT NULL,
    final_name_normalized     VARCHAR(255) NOT NULL,
    canonical_id              BIGINT,
    current_id                BIGINT,
    duplicate_id              BIGINT,
    final_id                  BIGINT
) ON COMMIT DROP;


INSERT INTO s31_author_merges (current_name_normalized,
                               duplicate_name_normalized,
                               final_name,
                               final_name_normalized,
                               canonical_id,
                               current_id,
                               duplicate_id,
                               final_id)
SELECT r.current_name_normalized,
       r.duplicate_name_normalized,
       r.final_name,
       r.final_name_normalized,
       COALESCE(f.id, c.id, d.id),
       c.id,
       d.id,
       f.id
FROM s31_author_merge_rules r
         LEFT JOIN authors c
                   ON c.name_normalized = r.current_name_normalized
         LEFT JOIN authors d
                   ON d.name_normalized = r.duplicate_name_normalized
         LEFT JOIN authors f
                   ON f.name_normalized = r.final_name_normalized;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s31_author_merges
                   WHERE canonical_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla de Script-31 no encuentra ningún autor candidato';
        END IF;
    END
$$;


INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                am.canonical_id
FROM s31_author_merges am
         JOIN book_authors ba
              ON ba.author_id IN (
                                  am.current_id,
                                  am.duplicate_id,
                                  am.final_id
                  )
WHERE am.canonical_id IS NOT NULL
  AND ba.author_id <> am.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s31_author_merges am
WHERE am.canonical_id IS NOT NULL
  AND ba.author_id IN (
                       am.current_id,
                       am.duplicate_id,
                       am.final_id
    )
  AND ba.author_id <> am.canonical_id;


DELETE
FROM authors a
    USING s31_author_merges am
WHERE am.canonical_id IS NOT NULL
  AND a.id IN (
               am.current_id,
               am.duplicate_id,
               am.final_id
    )
  AND a.id <> am.canonical_id;


UPDATE authors a
SET name            = am.final_name,
    name_normalized = am.final_name_normalized
FROM s31_author_merges am
WHERE a.id = am.canonical_id
  AND (
    a.name IS DISTINCT FROM am.final_name
        OR a.name_normalized IS DISTINCT FROM am.final_name_normalized
    );


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s31_author_merge_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla de Script-31 no terminó con exactamente un autor final';
        END IF;

        IF EXISTS (SELECT 1
                   FROM s31_author_merge_rules r
                            JOIN authors a
                                 ON a.name_normalized IN (
                                                          r.current_name_normalized,
                                                          r.duplicate_name_normalized
                                     )
                   WHERE a.name_normalized <> r.final_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron variantes históricas sin consolidar en Script-31';
        END IF;
    END
$$;



