-- =========================================================
-- Resolver todas las variantes + estado final
-- =========================================================

DROP TABLE IF EXISTS pg_temp.s32_candidate_names;

CREATE TEMP TABLE s32_candidate_names ON COMMIT DROP AS
SELECT group_id,
       name_normalized,
       FALSE AS is_final
FROM s32_merge_variants

UNION

SELECT group_id,
       final_name_normalized,
       TRUE AS is_final
FROM s32_merge_groups;


-- Un mismo name_normalized puede existir como máximo una vez.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s32_candidate_names cn
                            JOIN authors a
                                 ON a.name_normalized = cn.name_normalized
                   GROUP BY cn.group_id,
                            cn.name_normalized
                   HAVING COUNT(DISTINCT a.id) > 1) THEN
            RAISE EXCEPTION
                'Abortado: algún candidato de Script-32 resuelve ambiguamente';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s32_resolved_candidates;

CREATE TEMP TABLE s32_resolved_candidates ON COMMIT DROP AS
SELECT cn.group_id,
       a.id                       AS author_id,
       a.name,
       a.name_normalized,
       BOOL_OR(cn.is_final)       AS is_final,
       COUNT(DISTINCT ba.book_id) AS book_count
FROM s32_candidate_names cn
         JOIN authors a
              ON a.name_normalized = cn.name_normalized
         LEFT JOIN book_authors ba
                   ON ba.author_id = a.id
GROUP BY cn.group_id,
         a.id,
         a.name,
         a.name_normalized;


-- Cada grupo tiene que conservar al menos un autor posible.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s32_merge_groups mg
                            LEFT JOIN s32_resolved_candidates rc
                                      ON rc.group_id = mg.group_id
                   GROUP BY mg.group_id
                   HAVING COUNT(rc.author_id) = 0) THEN
            RAISE EXCEPTION
                'Abortado: algún grupo de Script-32 no encuentra ningún autor candidato';
        END IF;
    END
$$;


DROP TABLE IF EXISTS pg_temp.s32_canonical_authors;

CREATE TEMP TABLE s32_canonical_authors ON COMMIT DROP AS
SELECT group_id,
       author_id AS canonical_id
FROM (SELECT rc.*,
             ROW_NUMBER() OVER (
                 PARTITION BY rc.group_id
                 ORDER BY rc.book_count DESC,
                     rc.is_final DESC,
                     rc.author_id ASC
                 ) AS rn
      FROM s32_resolved_candidates rc) ranked
WHERE rn = 1;


-- Mover las relaciones de todos los registros no canónicos.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                ca.canonical_id
FROM s32_canonical_authors ca
         JOIN s32_resolved_candidates rc
              ON rc.group_id = ca.group_id
                  AND rc.author_id <> ca.canonical_id
         JOIN book_authors ba
              ON ba.author_id = rc.author_id
ON CONFLICT (book_id, author_id) DO NOTHING;


DELETE
FROM book_authors ba
    USING s32_canonical_authors ca,
        s32_resolved_candidates rc
WHERE rc.group_id = ca.group_id
  AND rc.author_id <> ca.canonical_id
  AND ba.author_id = rc.author_id;


DELETE
FROM authors a
    USING s32_canonical_authors ca,
        s32_resolved_candidates rc
WHERE rc.group_id = ca.group_id
  AND rc.author_id <> ca.canonical_id
  AND a.id = rc.author_id;


-- Aplicar el nombre final solamente después de eliminar las otras variantes.
UPDATE authors a
SET name            = mg.final_name,
    name_normalized = mg.final_name_normalized
FROM s32_canonical_authors ca
         JOIN s32_merge_groups mg
              ON mg.group_id = ca.group_id
WHERE a.id = ca.canonical_id
  AND (
    a.name IS DISTINCT FROM mg.final_name
        OR a.name_normalized IS DISTINCT FROM mg.final_name_normalized
    );


-- Postcondiciones.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s32_merge_groups mg
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = mg.final_name_normalized) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: algún grupo de Script-32 no terminó con exactamente un autor final';
        END IF;

        IF EXISTS (SELECT 1
                   FROM s32_merge_variants mv
                            JOIN s32_merge_groups mg
                                 ON mg.group_id = mv.group_id
                            JOIN authors a
                                 ON a.name_normalized = mv.name_normalized
                   WHERE mv.name_normalized <> mg.final_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron variantes históricas sin consolidar en Script-32';
        END IF;
    END
$$;



