DROP TABLE IF EXISTS pg_temp.s53_target_aliases;

CREATE TEMP TABLE s53_target_aliases
(
    historical_name_normalized VARCHAR(500) PRIMARY KEY,
    preferred_name_normalized  VARCHAR(500) NOT NULL
) ON COMMIT DROP;

INSERT INTO s53_target_aliases (historical_name_normalized,
                                preferred_name_normalized)
VALUES ('carzon walter', 'walter carzon'),
       ('parente iria g', 'iria g parente'),
       ('pascual selene m', 'selene m pascual'),
       ('fink nadia', 'nadia fink');



DO
$$
    BEGIN
        IF EXISTS (WITH composite_resolution AS (SELECT cg.group_id,
                                                        COUNT(a.id) AS matches
                                                 FROM s53_composite_groups cg
                                                          LEFT JOIN authors a
                                                                    ON a.name_normalized = cg.composite_name_normalized
                                                 GROUP BY cg.group_id)
                   SELECT 1
                   FROM composite_resolution
                   WHERE matches > 1) THEN
            RAISE EXCEPTION 'Abortado: algún autor compuesto fuente resuelve ambiguamente';
        END IF;
    END
$$;

DO
$$
    DECLARE
        missing_targets TEXT;
    BEGIN
        -- Cada nombre histórico o preferido puede resolver como máximo
        -- a un registro físico.
        IF EXISTS (SELECT 1
                   FROM s53_composite_targets ct
                            LEFT JOIN s53_target_aliases ta
                                      ON ta.historical_name_normalized = ct.target_name_normalized
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = ct.target_name_normalized) > 1
                      OR (
                       ta.preferred_name_normalized IS NOT NULL
                           AND (SELECT COUNT(*)
                                FROM authors a
                                WHERE a.name_normalized = ta.preferred_name_normalized) > 1
                       )) THEN
            RAISE EXCEPTION
                'Abortado: algún autor individual destino de Script-53 resuelve ambiguamente';
        END IF;


        -- Mostrar TODOS los targets que no pueden resolverse.
        SELECT STRING_AGG(
                       FORMAT(
                               'group_id=%s, historical=%s, preferred=%s',
                               x.group_id,
                               x.historical_name_normalized,
                               COALESCE(x.preferred_name_normalized, '<sin alias>')
                       ),
                       ' | '
                       ORDER BY x.group_id, x.historical_name_normalized
               )
        INTO missing_targets
        FROM (SELECT DISTINCT ct.group_id,
                              ct.target_name_normalized AS historical_name_normalized,
                              ta.preferred_name_normalized
              FROM s53_composite_targets ct
                       LEFT JOIN s53_target_aliases ta
                                 ON ta.historical_name_normalized = ct.target_name_normalized
              WHERE NOT EXISTS (SELECT 1
                                FROM authors a
                                WHERE a.name_normalized = ct.target_name_normalized
                                   OR (
                                    ta.preferred_name_normalized IS NOT NULL
                                        AND a.name_normalized = ta.preferred_name_normalized
                                    ))) x;


        IF missing_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'Abortado: Script-53 targets sin resolver: %',
                missing_targets;
        END IF;
    END
$$;


-- Resolver IDs localmente en este ambiente.
DROP TABLE IF EXISTS pg_temp.s53_resolved_composites;
CREATE TEMP TABLE s53_resolved_composites ON COMMIT DROP AS
SELECT cg.group_id,
       a.id   AS composite_author_id,
       a.name AS composite_author_name
FROM s53_composite_groups cg
         JOIN authors a
              ON a.name_normalized = cg.composite_name_normalized;

DROP TABLE IF EXISTS pg_temp.s53_resolved_targets;

CREATE TEMP TABLE s53_resolved_targets ON COMMIT DROP AS
SELECT ct.group_id,
       resolved.id   AS target_author_id,
       resolved.name AS target_author_name
FROM s53_composite_targets ct
         LEFT JOIN s53_target_aliases ta
                   ON ta.historical_name_normalized = ct.target_name_normalized
         JOIN LATERAL (
    SELECT a.id,
           a.name
    FROM authors a
    WHERE a.name_normalized = ct.target_name_normalized
       OR (
        ta.preferred_name_normalized IS NOT NULL
            AND a.name_normalized = ta.preferred_name_normalized
        )
    ORDER BY CASE
                 WHEN a.name_normalized = ta.preferred_name_normalized THEN 0
                 ELSE 1
                 END,
             a.id
    LIMIT 1
    ) resolved ON TRUE;


-- Snapshot de relaciones a transformar.
DROP TABLE IF EXISTS pg_temp.s53_composite_book_snapshot;
CREATE TEMP TABLE s53_composite_book_snapshot ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.group_id,
                rc.composite_author_id,
                rt.target_author_id
FROM s53_resolved_composites rc
         JOIN s53_resolved_targets rt
              ON rt.group_id = rc.group_id
         JOIN book_authors ba
              ON ba.author_id = rc.composite_author_id;

-- D) Vincular todos los autores individuales a todos los libros del compuesto.
INSERT INTO book_authors (book_id, author_id)
SELECT cbs.book_id,
       cbs.target_author_id
FROM s53_composite_book_snapshot cbs
ON CONFLICT (book_id, author_id) DO NOTHING;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s53_composite_book_snapshot cbs
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = cbs.book_id
                                          AND ba.author_id = cbs.target_author_id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no recibió todos los autores individuales';
        END IF;
    END
$$;

-- F) Eliminar relaciones hacia los autores compuestos.
DELETE
FROM book_authors ba
    USING s53_resolved_composites rc
WHERE ba.author_id = rc.composite_author_id;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s53_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_author_id) THEN
            RAISE EXCEPTION 'Abortado: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;

-- H) Eliminar Author compuestos.
DELETE
FROM authors a
    USING s53_resolved_composites rc
WHERE a.id = rc.composite_author_id;



-- ============================================================================
-- Historical cleanup batch Script-54
-- ============================================================================
-- ============================================================
-- LIMPIEZA PORTABLE FINAL DE AUTORÍAS COMPUESTAS RESIDUALES
--
-- Base de trabajo previa: 82.103 autores.
--
-- Principios:
-- - NO usa IDs hardcodeados.
-- - Los libros con relaciones activas se identifican por isbn_13.
-- - Los autores existentes se resuelven por name_normalized.
-- - Crea "Diego González Rivera" y "Enrique Martínez" sólo si no existen.
-- - No reutiliza "ENRIQUE M MARTINEZ": no está validado como la misma persona.
-- - Los registros basura "CUENTOS Y AVENTURAS" y "COLOREAR Y STICKERS"
--   se desvinculan y eliminan sin crear autores ficticios.
-- - Los compuestos sin libros se eliminan.
-- - Todo aborta ante ambigüedad.
--
-- IMPORTANTE:
-- ============================================================

-- ------------------------------------------------------------
-- 1. Autores individuales que deben existir.
-- ------------------------------------------------------------

INSERT INTO authors (name, name_normalized)
SELECT 'Diego González Rivera', 'diego gonzalez rivera'
WHERE NOT EXISTS (SELECT 1
                  FROM authors
                  WHERE name_normalized = 'diego gonzalez rivera');

INSERT INTO authors (name, name_normalized)
SELECT 'Enrique Martínez', 'enrique martinez'
WHERE NOT EXISTS (SELECT 1
                  FROM authors
                  WHERE name_normalized = 'enrique martinez');

