-- ------------------------------------------------------------
-- 3. Los isbn_13 afectados deben resolver exactamente una vez.
-- ------------------------------------------------------------

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT t.isbn_13,
                                COUNT(DISTINCT b.id) AS matches
                         FROM (SELECT DISTINCT isbn_13
                               FROM s54_final_book_author_targets) t
                                  LEFT JOIN books b
                                            ON b.isbn_13 = t.isbn_13
                         GROUP BY t.isbn_13
                         HAVING COUNT(DISTINCT b.id) <> 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún isbn_13 afectado no resuelve exactamente un libro';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 4. Cada autor destino debe resolver exactamente una vez.
-- ------------------------------------------------------------

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT t.target_name_normalized,
                                COUNT(a.id) AS matches
                         FROM (SELECT DISTINCT target_name_normalized
                               FROM s54_final_book_author_targets) t
                                  LEFT JOIN authors a
                                            ON a.name_normalized = t.target_name_normalized
                         GROUP BY t.target_name_normalized
                         HAVING COUNT(a.id) <> 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún autor destino no resuelve exactamente una vez';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 5. Todos los compuestos activos esperados deben existir una vez.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s54_active_composites;
CREATE TEMP TABLE s54_active_composites
(
    name_normalized VARCHAR(255) PRIMARY KEY
) ON COMMIT DROP;

INSERT INTO s54_active_composites (name_normalized)
