       ('goethe schiller'),
       ('rossi gonzalez'),
       ('oli natalia colombo'),
       ('esopo fedro'),
       ('oscar wilde y oski'),
       ('lev tolstoi decur'),
       ('oscar wilde oski');

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT ac.name_normalized,
                                COUNT(a.id) AS matches
                         FROM s54_active_composites ac
                                  LEFT JOIN authors a
                                            ON a.name_normalized = ac.name_normalized
                         GROUP BY ac.name_normalized
                         HAVING COUNT(a.id) > 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún autor compuesto activo no resuelve exactamente una vez';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 6. Snapshot de las relaciones actuales de los compuestos.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s54_affected_composite_relations;
CREATE TEMP TABLE s54_affected_composite_relations ON COMMIT DROP AS
SELECT a.id              AS composite_author_id,
       a.name            AS composite_author_name,
       a.name_normalized AS composite_name_normalized,
       ba.book_id,
       b.isbn_13,
       b.title
FROM s54_active_composites ac
         JOIN authors a
              ON a.name_normalized = ac.name_normalized
         LEFT JOIN book_authors ba
                   ON ba.author_id = a.id
         LEFT JOIN books b
                   ON b.id = ba.book_id;

-- Los compuestos con libros reales deben estar asociados sólo a los isbn_13
-- que auditamos. Las dos categorías basura son la excepción deliberada.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s54_affected_composite_relations acr
                   WHERE acr.book_id IS NOT NULL
                     AND acr.composite_name_normalized NOT IN (
                                                               'cuentos y aventuras',
                                                               'colorear y stickers'
                       )
                     AND NOT EXISTS (SELECT 1
                                     FROM s54_final_book_author_targets t
                                     WHERE t.isbn_13 = acr.isbn_13)) THEN
            RAISE EXCEPTION 'Abortado: un autor compuesto tiene un libro no contemplado por la migración';
        END IF;
    END
$$;


-- ------------------------------------------------------------
-- 8. Agregar autores individuales correctos.
-- ------------------------------------------------------------

INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT b.id,
                a.id
FROM s54_final_book_author_targets t
         JOIN books b
              ON b.isbn_13 = t.isbn_13
         JOIN authors a
              ON a.name_normalized = t.target_name_normalized
ON CONFLICT (book_id, author_id) DO NOTHING;

-- ------------------------------------------------------------
-- 9. Validar que todos los vínculos destino existen.
-- ------------------------------------------------------------

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s54_final_book_author_targets t
                            JOIN books b
                                 ON b.isbn_13 = t.isbn_13
                            JOIN authors a
                                 ON a.name_normalized = t.target_name_normalized
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = b.id
                                          AND ba.author_id = a.id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no recibió todos sus autores correctos';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 10. Eliminar relaciones hacia los 13 compuestos activos.
--     Incluye las categorías basura.
-- ------------------------------------------------------------

DELETE
FROM book_authors ba
    USING authors a, s54_active_composites ac
WHERE ba.author_id = a.id
  AND a.name_normalized = ac.name_normalized;

-- ------------------------------------------------------------
-- 11. Ningún compuesto activo debe conservar libros.
-- ------------------------------------------------------------

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s54_active_composites ac
                            JOIN authors a
                                 ON a.name_normalized = ac.name_normalized
                            JOIN book_authors ba
                                 ON ba.author_id = a.id) THEN
            RAISE EXCEPTION 'Abortado: quedaron libros vinculados a autores compuestos';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 12. Eliminar los 13 compuestos activos.
-- ------------------------------------------------------------

DELETE
FROM authors a
    USING s54_active_composites ac
WHERE a.name_normalized = ac.name_normalized;

-- ------------------------------------------------------------
-- 13. Eliminar los 4 compuestos residuales sin libros.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s54_zero_book_composites;
