-- ============================================================================
-- Historical cleanup batch Script-55
-- ============================================================================
-- ============================================================
-- LIMPIEZA PORTABLE - CASOS VALIDADOS
--
-- Casos:
-- 1) PENNY, MARTIN / MARTIN, PENNY              -> Martin Penny
-- 2) MARTIN SANTIAGO / SANTIAGO MARTIN          -> Santiago Martín
-- 3) MATE REYES / REYES MATE                    -> Reyes Mate
-- 4) SILVINA ROCHA - MEY / Mey Silvina Rocha    -> Silvina Rocha + Mey Clerici
-- 5) RADICE TURCONI / TURCONI RADICE             -> Teresa Radice + Stefano Turconi
--
-- MARTIN/MUÑOZ queda EXCLUIDO deliberadamente.
--
-- Portable:
-- - Sin IDs hardcodeados.
-- - Libros resueltos por books.isbn_13.
-- - Autores resueltos por authors.name_normalized.
-- - Abortará ante cualquier resolución ambigua.
--
-- ============================================================

-- ------------------------------------------------------------
-- 1. MERGES DE UNA SOLA PERSONA
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s55_person_merge_groups;
CREATE TEMP TABLE s55_person_merge_groups
(
    group_id              INTEGER PRIMARY KEY,
    final_name            VARCHAR(255) NOT NULL,
    final_name_normalized VARCHAR(255) NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO s55_person_merge_groups (group_id, final_name, final_name_normalized)
VALUES (1, 'Martin Penny', 'martin penny'),
       (2, 'Santiago Martín', 'santiago martin'),
       (3, 'Reyes Mate', 'reyes mate');

DROP TABLE IF EXISTS pg_temp.s55_person_merge_variants;
CREATE TEMP TABLE s55_person_merge_variants
(
    group_id        INTEGER      NOT NULL REFERENCES s55_person_merge_groups (group_id),
    name_normalized VARCHAR(255) NOT NULL,
    PRIMARY KEY (group_id, name_normalized)
) ON COMMIT DROP;

INSERT INTO s55_person_merge_variants (group_id, name_normalized)
VALUES (1, 'penny martin'),
       (1, 'martin penny'),

       (2, 'martin santiago'),
       (2, 'santiago martin'),

       (3, 'mate reyes'),
       (3, 'reyes mate');

-- Cada variante debe resolver exactamente una vez.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT pmv.group_id,
                                pmv.name_normalized,
                                COUNT(a.id) AS matches
                         FROM s55_person_merge_variants pmv
                                  LEFT JOIN authors a
                                            ON a.name_normalized = pmv.name_normalized
                         GROUP BY pmv.group_id,
                                  pmv.name_normalized
                         HAVING COUNT(a.id) > 1) x) THEN
            RAISE EXCEPTION 'Abortado: alguna variante de merge personal es ambigua';
        END IF;
    END
$$;

DROP TABLE IF EXISTS pg_temp.s55_resolved_person_members;
CREATE TEMP TABLE s55_resolved_person_members ON COMMIT DROP AS
SELECT pmv.group_id,
       a.id              AS author_id,
       a.name,
       a.name_normalized,
       COUNT(ba.book_id) AS book_count
FROM s55_person_merge_variants pmv
         JOIN authors a
              ON a.name_normalized = pmv.name_normalized
         LEFT JOIN book_authors ba
                   ON ba.author_id = a.id
GROUP BY pmv.group_id,
         a.id,
         a.name,
         a.name_normalized;

DROP TABLE IF EXISTS pg_temp.s55_person_canonicals;
CREATE TEMP TABLE s55_person_canonicals ON COMMIT DROP AS
SELECT DISTINCT ON (rpm.group_id) rpm.group_id,
                                  rpm.author_id AS canonical_id,
                                  pmg.final_name,
                                  pmg.final_name_normalized
FROM s55_resolved_person_members rpm
         JOIN s55_person_merge_groups pmg
              ON pmg.group_id = rpm.group_id
ORDER BY rpm.group_id,
         rpm.book_count DESC,
         rpm.author_id ASC;


-- Copiar vínculos de libros al canonical.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                pc.canonical_id
FROM s55_resolved_person_members rpm
         JOIN s55_person_canonicals pc
              ON pc.group_id = rpm.group_id
         JOIN book_authors ba
              ON ba.author_id = rpm.author_id
WHERE rpm.author_id <> pc.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;

-- Borrar vínculos de variantes.
DELETE
FROM book_authors ba
    USING s55_resolved_person_members rpm, s55_person_canonicals pc
WHERE pc.group_id = rpm.group_id
  AND rpm.author_id <> pc.canonical_id
  AND ba.author_id = rpm.author_id;

-- Borrar variantes.
DELETE
FROM authors a
    USING s55_resolved_person_members rpm, s55_person_canonicals pc
WHERE pc.group_id = rpm.group_id
  AND rpm.author_id <> pc.canonical_id
  AND a.id = rpm.author_id;

-- Normalizar el canonical.
UPDATE authors a
SET name            = pc.final_name,
    name_normalized = pc.final_name_normalized
FROM s55_person_canonicals pc
WHERE a.id = pc.canonical_id;

