-- 2. DESCOMPOSICIÓN: SILVINA ROCHA + MEY
-- ------------------------------------------------------------

-- Crear autores individuales faltantes de forma portable.
INSERT INTO authors (name, name_normalized)
SELECT 'Teresa Radice', 'teresa radice'
WHERE NOT EXISTS (SELECT 1
                  FROM authors
                  WHERE name_normalized = 'teresa radice');

INSERT INTO authors (name, name_normalized)
SELECT 'Stefano Turconi', 'stefano turconi'
WHERE NOT EXISTS (SELECT 1
                  FROM authors
                  WHERE name_normalized = 'stefano turconi');


DROP TABLE IF EXISTS pg_temp.s55_composite_book_targets;
CREATE TEMP TABLE s55_composite_book_targets
(
    isbn_13                VARCHAR(32)  NOT NULL,
    target_name_normalized VARCHAR(255) NOT NULL,
    PRIMARY KEY (isbn_13, target_name_normalized)
) ON COMMIT DROP;

INSERT INTO s55_composite_book_targets (isbn_13, target_name_normalized)
VALUES
    -- Por qué los elefantes prefieren jugar a la mancha
    ('9789871374311', 'silvina rocha'),
    ('9789871374311', 'clerici mey'),
    ('9789878371757', 'silvina rocha'),
    ('9789878371757', 'clerici mey'),

    -- Teresa Radice + Stefano Turconi
    ('9788416507702', 'teresa radice'),
    ('9788416507702', 'stefano turconi'),
    ('9788417294366', 'teresa radice'),
    ('9788417294366', 'stefano turconi'),
    ('9788416507085', 'teresa radice'),
    ('9788416507085', 'stefano turconi');

-- Cada ISBN debe resolver exactamente un libro.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT t.isbn_13,
                                COUNT(DISTINCT b.id) AS matches
                         FROM (SELECT DISTINCT isbn_13
                               FROM s55_composite_book_targets) t
                                  LEFT JOIN books b
                                            ON b.isbn_13 = t.isbn_13
                         GROUP BY t.isbn_13
                         HAVING COUNT(DISTINCT b.id) <> 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún isbn_13 no resuelve exactamente un libro';
        END IF;
    END
$$;

-- Cada autor destino debe existir exactamente una vez.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT t.target_name_normalized,
                                COUNT(a.id) AS matches
                         FROM (SELECT DISTINCT target_name_normalized
                               FROM s55_composite_book_targets) t
                                  LEFT JOIN authors a
                                            ON a.name_normalized = t.target_name_normalized
                         GROUP BY t.target_name_normalized
                         HAVING COUNT(a.id) > 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún autor destino de una autoría compuesta es ambigua';
        END IF;
    END
$$;

-- Compuestos que deben desaparecer.
DROP TABLE IF EXISTS pg_temp.s55_decomposed_composites;
CREATE TEMP TABLE s55_decomposed_composites
(
    name_normalized VARCHAR(255) PRIMARY KEY
) ON COMMIT DROP;

INSERT INTO s55_decomposed_composites (name_normalized)
VALUES ('silvina rocha mey'),
       ('mey silvina rocha'),
       ('radice turconi'),
       ('turconi radice');

-- Deben existir exactamente una vez.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT dc.name_normalized,
                                COUNT(a.id) AS matches
                         FROM s55_decomposed_composites dc
                                  LEFT JOIN authors a
                                            ON a.name_normalized = dc.name_normalized
                         GROUP BY dc.name_normalized
                         HAVING COUNT(a.id) > 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún autor compuesto a descomponer es ambigua';
        END IF;
    END
$$;


-- Agregar autores individuales.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT b.id,
                a.id
FROM s55_composite_book_targets cbt
         JOIN books b
              ON b.isbn_13 = cbt.isbn_13
         JOIN authors a
              ON a.name_normalized = cbt.target_name_normalized
ON CONFLICT (book_id, author_id) DO NOTHING;

-- Verificar que todos los vínculos destino quedaron creados.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s55_composite_book_targets cbt
                            JOIN books b
                                 ON b.isbn_13 = cbt.isbn_13
                            JOIN authors a
                                 ON a.name_normalized = cbt.target_name_normalized
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = b.id
                                          AND ba.author_id = a.id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;

-- Validar que los compuestos sólo estén asociados a los ISBN auditados.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s55_decomposed_composites dc
                            JOIN authors a
                                 ON a.name_normalized = dc.name_normalized
                            JOIN book_authors ba
                                 ON ba.author_id = a.id
                            JOIN books b
                                 ON b.id = ba.book_id
                   WHERE b.isbn_13 NOT IN (SELECT DISTINCT isbn_13
                                           FROM s55_composite_book_targets)) THEN
            RAISE EXCEPTION 'Abortado: un autor compuesto tiene libros no contemplados';
        END IF;
    END
$$;

-- Eliminar relaciones hacia compuestos.
DELETE
FROM book_authors ba
    USING authors a, s55_decomposed_composites dc
WHERE ba.author_id = a.id
  AND a.name_normalized = dc.name_normalized;

-- Los compuestos deben quedar sin relaciones.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s55_decomposed_composites dc
                            JOIN authors a
                                 ON a.name_normalized = dc.name_normalized
                            JOIN book_authors ba
                                 ON ba.author_id = a.id) THEN
            RAISE EXCEPTION 'Abortado: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;

-- Eliminar compuestos.
DELETE
FROM authors a
    USING s55_decomposed_composites dc
WHERE a.name_normalized = dc.name_normalized;

