-- ------------------------------------------------------------
-- B) Crear autores individuales que falten.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s57_authors_before_creation;
CREATE TEMP TABLE s57_authors_before_creation ON COMMIT DROP AS
SELECT DISTINCT ct.target_name_normalized
FROM s57_cleanup_targets ct
         JOIN authors a
              ON a.name_normalized = ct.target_name_normalized;

INSERT INTO authors (name, name_normalized)
SELECT DISTINCT ct.final_name,
                ct.target_name_normalized
FROM s57_cleanup_targets ct
WHERE NOT EXISTS (SELECT 1
                  FROM authors a
                  WHERE a.name_normalized = ct.target_name_normalized);



DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT ct.group_id,
                                ct.target_name_normalized,
                                COUNT(a.id) AS matches
                         FROM s57_cleanup_targets ct
                                  LEFT JOIN authors a
                                            ON a.name_normalized = ct.target_name_normalized
                         GROUP BY ct.group_id, ct.target_name_normalized
                         HAVING COUNT(a.id) <> 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún autor individual destino no resuelve exactamente una vez';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- D) Resolver IDs locales.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s57_resolved_composites;
CREATE TEMP TABLE s57_resolved_composites ON COMMIT DROP AS
SELECT cc.group_id,
       a.id   AS composite_author_id,
       a.name AS composite_author_name,
       a.name_normalized
FROM s57_cleanup_composites cc
         JOIN authors a
              ON a.name_normalized = cc.composite_name_normalized;

DROP TABLE IF EXISTS pg_temp.s57_resolved_targets;
CREATE TEMP TABLE s57_resolved_targets ON COMMIT DROP AS
SELECT ct.group_id,
       a.id   AS target_author_id,
       a.name AS target_author_name,
       a.name_normalized
FROM s57_cleanup_targets ct
         JOIN authors a
              ON a.name_normalized = ct.target_name_normalized;


-- ------------------------------------------------------------
-- E) Snapshot de relaciones y traslado.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s57_composite_book_snapshot;
CREATE TEMP TABLE s57_composite_book_snapshot ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.group_id,
                rc.composite_author_id,
                rt.target_author_id
FROM s57_resolved_composites rc
         JOIN s57_resolved_targets rt ON rt.group_id = rc.group_id
         JOIN book_authors ba ON ba.author_id = rc.composite_author_id;

INSERT INTO book_authors (book_id, author_id)
SELECT cbs.book_id,
       cbs.target_author_id
FROM s57_composite_book_snapshot cbs
ON CONFLICT (book_id, author_id) DO NOTHING;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s57_composite_book_snapshot cbs
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = cbs.book_id
                                          AND ba.author_id = cbs.target_author_id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no recibió todos los autores individuales';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- F) Eliminar relaciones y Author compuestos.
-- ------------------------------------------------------------

DELETE
FROM book_authors ba
    USING s57_resolved_composites rc
WHERE ba.author_id = rc.composite_author_id;

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s57_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_author_id) THEN
            RAISE EXCEPTION 'Abortado: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;

DELETE
FROM authors a
    USING s57_resolved_composites rc
WHERE a.id = rc.composite_author_id;



