-- MERGE PORTABLE DE 10 AUTORES INDIVIDUALES DUPLICADOS
-- Base esperada antes de ejecutar: 82.044 autores
-- Reducción esperada: 10
-- Conteo esperado tras COMMIT: 82.034
--
-- Sin IDs hardcodeados.
-- Canónico: variante con mayor cantidad de libros.
-- Desempate: menor id.
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s59_merge_groups;
CREATE TEMP TABLE s59_merge_groups
(
    group_id              INTEGER PRIMARY KEY,
    final_name            VARCHAR(255) NOT NULL,
