DROP TABLE IF EXISTS pg_temp.s59_merge_variants;
CREATE TEMP TABLE s59_merge_variants
(
    group_id        INTEGER      NOT NULL REFERENCES s59_merge_groups (group_id),
    name_normalized VARCHAR(255) NOT NULL,
    PRIMARY KEY (group_id, name_normalized)
) ON COMMIT DROP;

INSERT INTO s59_merge_variants (group_id, name_normalized)
VALUES (1, 'martin azcurra'),
