DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT mv.group_id,
                                mv.name_normalized,
                                COUNT(a.id) AS matches
                         FROM s59_merge_variants mv
                                  LEFT JOIN authors a
                                            ON a.name_normalized = mv.name_normalized
                         GROUP BY mv.group_id,
                                  mv.name_normalized
                         HAVING COUNT(a.id) > 1) x) THEN
            RAISE EXCEPTION 'Abortado: alguna variante no resuelve exactamente una vez';
        END IF;
    END
$$;

-- B) Resolver miembros y conteos.
DROP TABLE IF EXISTS pg_temp.s59_resolved_members;
CREATE TEMP TABLE s59_resolved_members ON COMMIT DROP AS
SELECT mv.group_id,
       a.id              AS author_id,
       a.name,
       a.name_normalized,
       COUNT(ba.book_id) AS book_count
FROM s59_merge_variants mv
         JOIN authors a
              ON a.name_normalized = mv.name_normalized
         LEFT JOIN book_authors ba
                   ON ba.author_id = a.id
GROUP BY mv.group_id,
         a.id,
         a.name,
         a.name_normalized;

-- C) Elegir canónico por mayor book_count; desempate menor id.
DROP TABLE IF EXISTS pg_temp.s59_canonical_authors;
CREATE TEMP TABLE s59_canonical_authors ON COMMIT DROP AS
SELECT DISTINCT ON (rm.group_id) rm.group_id,
                                 rm.author_id  AS canonical_id,
                                 mg.final_name,
                                 mg.final_name_normalized,
                                 rm.book_count AS canonical_book_count
FROM s59_resolved_members rm
         JOIN s59_merge_groups mg
              ON mg.group_id = rm.group_id
ORDER BY rm.group_id,
         rm.book_count DESC,
         rm.author_id ASC;


-- D) Copiar relaciones hacia canónico.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                ca.canonical_id
FROM s59_resolved_members rm
         JOIN s59_canonical_authors ca
              ON ca.group_id = rm.group_id
         JOIN book_authors ba
              ON ba.author_id = rm.author_id
WHERE rm.author_id <> ca.canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;

-- E) Verificar que todos los libros de variantes estén en canónico.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s59_resolved_members rm
                            JOIN s59_canonical_authors ca
                                 ON ca.group_id = rm.group_id
                            JOIN book_authors ba_source
                                 ON ba_source.author_id = rm.author_id
                            LEFT JOIN book_authors ba_target
                                      ON ba_target.book_id = ba_source.book_id
                                          AND ba_target.author_id = ca.canonical_id
                   WHERE rm.author_id <> ca.canonical_id
                     AND ba_target.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no fue copiado al autor canónico';
        END IF;
    END
$$;

-- F) Eliminar relaciones de variantes.
DELETE
FROM book_authors ba
    USING s59_resolved_members rm, s59_canonical_authors ca
WHERE ca.group_id = rm.group_id
  AND rm.author_id <> ca.canonical_id
  AND ba.author_id = rm.author_id;

-- G) Eliminar autores variantes.
DELETE
FROM authors a
    USING s59_resolved_members rm, s59_canonical_authors ca
WHERE ca.group_id = rm.group_id
  AND rm.author_id <> ca.canonical_id
  AND a.id = rm.author_id;

-- H) Normalizar nombre final del canónico.
UPDATE authors a
SET name            = ca.final_name,
    name_normalized = ca.final_name_normalized
FROM s59_canonical_authors ca
WHERE a.id = ca.canonical_id;



