-- ============================================================================
-- Historical cleanup batch Script-61
-- ============================================================================
-- ============================================================
-- MERGE PORTABLE DE 8 AUTORES INDIVIDUALES DUPLICADOS
--
-- Sin IDs hardcodeados.
-- Canonical por name_normalized explícito.
-- Mueve book_authors, valida y elimina el duplicado.
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s61_tmp_author_merge;
CREATE TEMP TABLE s61_tmp_author_merge
(
    final_name           VARCHAR(255) NOT NULL,
    canonical_normalized VARCHAR(255) NOT NULL UNIQUE,
    duplicate_normalized VARCHAR(255) NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO s61_tmp_author_merge (final_name, canonical_normalized, duplicate_normalized)
VALUES ('Diego Moscato', 'diego moscato', 'moscato diego'),
       ('Elisabetta Kuky Drudi', 'elisabetta kuky drudi', 'kuky drudi elisabetta'),
       ('Eric Carle', 'eric carle', 'carle eric'),
       ('Fernando Rossia', 'fernando rossia', 'rossia fernando'),
       ('Gerardo Baró', 'gerardo baro', 'baro gerardo'),
       ('Laura Michell', 'laura michell', 'michell laura'),
       ('Pablo Tambuscio', 'pablo tambuscio', 'tambuscio pablo'),
       ('Stephanie Richard', 'stephanie richard', 'richard stephanie');


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT m.final_name,
                                COUNT(DISTINCT c.id) AS canonical_matches,
                                COUNT(DISTINCT d.id) AS duplicate_matches
                         FROM s61_tmp_author_merge m
                                  LEFT JOIN authors c
                                            ON c.name_normalized = m.canonical_normalized
                                  LEFT JOIN authors d
                                            ON d.name_normalized = m.duplicate_normalized
                         GROUP BY m.final_name
                         HAVING COUNT(DISTINCT c.id) <> 1
                             OR COUNT(DISTINCT d.id) > 1) x) THEN
            RAISE EXCEPTION 'Abortado: algún par no resuelve exactamente una vez';
        END IF;
    END
$$;

-- B) Resolver IDs.
DROP TABLE IF EXISTS pg_temp.s61_resolved_merge;
CREATE TEMP TABLE s61_resolved_merge ON COMMIT DROP AS
SELECT m.final_name,
       m.canonical_normalized,
       m.duplicate_normalized,
       c.id AS canonical_id,
       d.id AS duplicate_id
FROM s61_tmp_author_merge m
         JOIN authors c
              ON c.name_normalized = m.canonical_normalized
         JOIN authors d
              ON d.name_normalized = m.duplicate_normalized;


-- C) Copiar relaciones del duplicado al canónico.
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                rm.canonical_id
FROM s61_resolved_merge rm
         JOIN book_authors ba
              ON ba.author_id = rm.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;

-- D) Verificar que todos los libros del duplicado estén ahora en el canónico.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s61_resolved_merge rm
                            JOIN book_authors bd
                                 ON bd.author_id = rm.duplicate_id
                            LEFT JOIN book_authors bc
                                      ON bc.book_id = bd.book_id
                                          AND bc.author_id = rm.canonical_id
                   WHERE bc.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no fue copiado al autor canónico';
        END IF;
    END
$$;

-- E) Eliminar relaciones del duplicado.
DELETE
FROM book_authors ba
    USING s61_resolved_merge rm
WHERE ba.author_id = rm.duplicate_id;

-- F) Eliminar autores duplicados.
DELETE
FROM authors a
    USING s61_resolved_merge rm
WHERE a.id = rm.duplicate_id;

-- G) Normalizar nombre final del canónico.
UPDATE authors a
SET name            = rm.final_name,
    name_normalized = rm.canonical_normalized
FROM s61_resolved_merge rm
WHERE a.id = rm.canonical_id;



