SELECT cc.group_id, a.id AS composite_author_id, a.name AS composite_author_name
FROM s65_cleanup_composites cc
         JOIN authors a ON a.name_normalized = cc.composite_name_normalized;

DROP TABLE IF EXISTS pg_temp.s65_resolved_targets;
CREATE TEMP TABLE s65_resolved_targets ON COMMIT DROP AS
SELECT ct.group_id, a.id AS target_author_id, a.name AS target_author_name
FROM s65_cleanup_targets ct
         JOIN authors a ON a.name_normalized = ct.target_name_normalized;


DROP TABLE IF EXISTS pg_temp.s65_composite_book_snapshot;
CREATE TEMP TABLE s65_composite_book_snapshot ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.group_id,
                rc.composite_author_id,
                rt.target_author_id
FROM s65_resolved_composites rc
         JOIN s65_resolved_targets rt ON rt.group_id = rc.group_id
         JOIN book_authors ba ON ba.author_id = rc.composite_author_id;

INSERT INTO book_authors (book_id, author_id)
SELECT book_id, target_author_id
FROM s65_composite_book_snapshot
ON CONFLICT (book_id, author_id) DO NOTHING;

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s65_composite_book_snapshot cbs
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = cbs.book_id
                                          AND ba.author_id = cbs.target_author_id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION 'Abortado: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;

DELETE
FROM book_authors ba
    USING s65_resolved_composites rc
WHERE ba.author_id = rc.composite_author_id;

DELETE
FROM authors a
    USING s65_resolved_composites rc
WHERE a.id = rc.composite_author_id;



-- ============================================================================
-- Historical cleanup batch Script-66
-- ============================================================================
-- Script-66 rewritten: resolve source and target by normalized names.
DROP TABLE IF EXISTS pg_temp.s66_merge_rules;
CREATE TEMP TABLE s66_merge_rules
(
    source_normalized VARCHAR(255) PRIMARY KEY,
    target_normalized VARCHAR(255) UNIQUE NOT NULL,
    target_name       VARCHAR(255)        NOT NULL
) ON COMMIT DROP;

INSERT INTO s66_merge_rules (source_normalized, target_normalized, target_name)
VALUES ('al mariana', 'mariana al', 'Mariana Al'),
       ('busch maria', 'maria busch', 'María Busch'),
       ('rodriguez maria cecilia', 'maria cecilia rodriguez', 'María Cecilia Rodríguez'),
       ('dadon jose roberto', 'jose roberto dadon', 'José Roberto Dadón'),
       ('nigra fabio', 'fabio nigra', 'Fabio Nigra'),
       ('morvillo silvina', 'silvina morvillo', 'Silvina Morvillo');

DO
$$
    BEGIN
        IF EXISTS (SELECT r.source_normalized
                   FROM s66_merge_rules r
                            LEFT JOIN authors a ON a.name_normalized = r.source_normalized
                   GROUP BY r.source_normalized
                   HAVING COUNT(a.id) > 1) OR EXISTS (SELECT r.target_normalized
                                                      FROM s66_merge_rules r
                                                               LEFT JOIN authors a ON a.name_normalized = r.target_normalized
                                                      GROUP BY r.target_normalized
                                                      HAVING COUNT(a.id) <> 1) THEN
            RAISE EXCEPTION 'V69/Script-66: target author is missing/ambiguous or source author is ambiguous';
        END IF;
    END
$$;

DROP TABLE IF EXISTS pg_temp.s66_resolved;
CREATE TEMP TABLE s66_resolved ON COMMIT DROP AS
SELECT s.id AS source_id,
       t.id AS target_id,
       r.target_name,
       r.target_normalized
FROM s66_merge_rules r
         JOIN authors s ON s.name_normalized = r.source_normalized
         JOIN authors t ON t.name_normalized = r.target_normalized;

INSERT INTO book_authors (book_id, author_id)
SELECT ba.book_id, r.target_id
FROM s66_resolved r
         JOIN book_authors ba ON ba.author_id = r.source_id
ON CONFLICT (book_id, author_id) DO NOTHING;

DELETE
FROM book_authors ba
    USING s66_resolved r
WHERE ba.author_id = r.source_id;

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM book_authors ba
                            JOIN s66_resolved r ON r.source_id = ba.author_id) THEN
            RAISE EXCEPTION 'V69/Script-66: source relationships remain after reassignment';
        END IF;
    END
$$;

DELETE
FROM authors a
    USING s66_resolved r
WHERE a.id = r.source_id;

UPDATE authors a
SET name            = r.target_name,
    name_normalized = r.target_normalized
FROM s66_resolved r
WHERE a.id = r.target_id
  AND (a.name IS DISTINCT FROM r.target_name OR a.name_normalized IS DISTINCT FROM r.target_normalized);



-- ============================================================================
-- Historical cleanup batch Script-68
-- ============================================================================
-- ============================================================
-- CARLOS CANALES + MIGUEL DEL REY
-- Limpieza portable de todas las variantes restantes.
-- Sin IDs hardcodeados.
-- ============================================================

-- 1. Garantizar que existan los dos autores individuales.

INSERT INTO authors (name, name_normalized)
SELECT 'Carlos Canales', 'carlos canales'
WHERE NOT EXISTS (SELECT 1
                  FROM authors
                  WHERE name_normalized = 'carlos canales');

INSERT INTO authors (name, name_normalized)
SELECT 'Miguel del Rey', 'miguel del rey'
WHERE NOT EXISTS (SELECT 1
                  FROM authors
                  WHERE name_normalized = 'miguel del rey');


-- 2. Cada destino debe resolver exactamente una vez.

DO
$$
    BEGIN
        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'carlos canales') <> 1 THEN
            RAISE EXCEPTION
                'Abortado: Carlos Canales no resuelve exactamente una vez';
        END IF;

        IF (SELECT COUNT(*)
            FROM authors
            WHERE name_normalized = 'miguel del rey') <> 1 THEN
            RAISE EXCEPTION
                'Abortado: Miguel del Rey no resuelve exactamente una vez';
        END IF;
    END
$$;


-- 3. Variantes compuestas que sabemos que corresponden
--    a Carlos Canales + Miguel del Rey.

DROP TABLE IF EXISTS pg_temp.s68_canales_del_rey_composites;

CREATE TEMP TABLE s68_canales_del_rey_composites
(
    name_normalized VARCHAR(255) PRIMARY KEY
) ON COMMIT DROP;

INSERT INTO s68_canales_del_rey_composites (name_normalized)
VALUES ('canales c del rey m'),
       ('canales c y del rey'),
       ('del rey m y canales'),
       ('canales c del rey'),
       ('del rey m canales c'),
       ('del rey m canales'),
       ('del rey miguel canales carlos');


-- 5. Deben existir las 7 variantes esperadas.

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s68_canales_del_rey_composites c
                            LEFT JOIN authors a
                                      ON a.name_normalized = c.name_normalized
                   GROUP BY c.name_normalized
                   HAVING COUNT(a.id) > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna variante de Canales/Del Rey resuelve ambiguamente';
        END IF;
    END
$$;


-- 6. Snapshot de todos los libros afectados.

DROP TABLE IF EXISTS pg_temp.s68_canales_del_rey_books;

CREATE TEMP TABLE s68_canales_del_rey_books ON COMMIT DROP AS
SELECT DISTINCT ba.book_id
FROM s68_canales_del_rey_composites c
         JOIN authors a
              ON a.name_normalized = c.name_normalized
         JOIN book_authors ba
              ON ba.author_id = a.id;


-- 7. Agregar Carlos Canales a los 14 libros.

INSERT INTO book_authors (book_id, author_id)
SELECT cb.book_id,
       a.id
FROM s68_canales_del_rey_books cb
         CROSS JOIN authors a
WHERE a.name_normalized = 'carlos canales'
ON CONFLICT (book_id, author_id) DO NOTHING;


-- 8. Agregar Miguel del Rey a los 14 libros.

INSERT INTO book_authors (book_id, author_id)
SELECT cb.book_id,
       a.id
FROM s68_canales_del_rey_books cb
         CROSS JOIN authors a
WHERE a.name_normalized = 'miguel del rey'
ON CONFLICT (book_id, author_id) DO NOTHING;


-- 9. Verificar que los dos autores quedaron en todos los libros.

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s68_canales_del_rey_books cb
                            CROSS JOIN (VALUES ('carlos canales'),
                                               ('miguel del rey')) AS target(name_normalized)
                            JOIN authors a
                                 ON a.name_normalized = target.name_normalized
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = cb.book_id
                                          AND ba.author_id = a.id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: algún libro no recibió ambos autores individuales';
        END IF;
    END
$$;


-- 10. Eliminar vínculos hacia todos los compuestos.

DELETE
FROM book_authors ba
    USING authors a, s68_canales_del_rey_composites c
WHERE ba.author_id = a.id
  AND a.name_normalized = c.name_normalized;


-- 11. Ningún compuesto debe conservar libros.

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s68_canales_del_rey_composites c
                            JOIN authors a
                                 ON a.name_normalized = c.name_normalized
                            JOIN book_authors ba
                                 ON ba.author_id = a.id) THEN
            RAISE EXCEPTION
                'Abortado: alguna variante compuesta conserva libros';
        END IF;
    END
$$;


-- 12. Eliminar las 7 variantes compuestas.

DELETE
FROM authors a
    USING s68_canales_del_rey_composites c
WHERE a.name_normalized = c.name_normalized;



