-- Las relaciones origen históricas pueden existir 0..1 veces.
-- 0 significa que la limpieza ya fue aplicada previamente.
-- >1 representa una ambigüedad real.

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT s.isbn_13,
                                s.source_author_name,
                                COUNT(ba.book_id) AS matches
                         FROM s69_mass_source_relations s
                                  LEFT JOIN books b
                                            ON b.isbn_13 = s.isbn_13
                                  LEFT JOIN authors a
                                            ON a.name = s.source_author_name
                                  LEFT JOIN book_authors ba
                                            ON ba.book_id = b.id
                                                AND ba.author_id = a.id
                         GROUP BY s.isbn_13,
                                  s.source_author_name
                         HAVING COUNT(ba.book_id) > 1) x) THEN
            RAISE EXCEPTION
                'Abortado: alguna relación origen de Script-69 resuelve ambiguamente';
        END IF;
    END
$$;


-- ------------------------------------------------------------
-- 5) Agregar relaciones correctas.
-- ------------------------------------------------------------

INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT b.id,
                a.id
FROM s69_mass_isbn_targets t
         JOIN books b
              ON b.isbn_13 = t.isbn_13
         JOIN authors a
              ON a.name_normalized = t.target_name_normalized
ON CONFLICT (book_id, author_id) DO NOTHING;

-- Verificar primero que CADA destino resuelva exactamente a un autor.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT t.isbn_13,
                                t.target_name_normalized,
                                COUNT(a.id) AS author_matches
                         FROM s69_mass_isbn_targets t
                                  LEFT JOIN authors a
                                            ON a.name_normalized = t.target_name_normalized
                         GROUP BY t.isbn_13,
                                  t.target_name_normalized
                         HAVING COUNT(a.id) <> 1) x) THEN
            RAISE EXCEPTION
                'Abortado: algún autor destino de un ISBN no resuelve exactamente una vez';
        END IF;
    END
$$;

-- Verificar después que CADA relación destino exista en book_authors.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s69_mass_isbn_targets t
                            JOIN books b
                                 ON b.isbn_13 = t.isbn_13
                            JOIN authors a
                                 ON a.name_normalized = t.target_name_normalized
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = b.id
                                          AND ba.author_id = a.id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: algún ISBN no recibió todos sus autores destino';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 6) Retirar únicamente la relación origen auditada.
--    No se tocan otros autores que el libro pudiera tener.
-- ------------------------------------------------------------

DELETE
FROM book_authors ba
    USING s69_mass_source_relations s, books b, authors a
WHERE b.isbn_13 = s.isbn_13
  AND a.name = s.source_author_name
  AND ba.book_id = b.id
  AND ba.author_id = a.id;

-- Deben haber desaparecido todas las relaciones origen.
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s69_mass_source_relations s
                            JOIN books b
                                 ON b.isbn_13 = s.isbn_13
                            JOIN authors a
                                 ON a.name = s.source_author_name
                            JOIN book_authors ba
                                 ON ba.book_id = b.id
                                     AND ba.author_id = a.id) THEN
            RAISE EXCEPTION
                'Abortado: quedó alguna relación origen después de la reasignación';
        END IF;
    END
$$;

-- ------------------------------------------------------------
-- 7) Eliminar autores origen que hayan quedado sin ningún libro.
--    Sólo autores que participaron como origen en esta pasada.
-- ------------------------------------------------------------

DROP TABLE IF EXISTS pg_temp.s69_mass_source_authors;
CREATE TEMP TABLE s69_mass_source_authors ON COMMIT DROP AS
SELECT DISTINCT source_author_name
FROM s69_mass_source_relations;

DELETE
FROM authors a
    USING s69_mass_source_authors s
WHERE a.name = s.source_author_name
  AND NOT EXISTS (SELECT 1
                  FROM book_authors ba
                  WHERE ba.author_id = a.id);



