-- ============================================================
-- 1) MERGE DE DUPLICADOS INDIVIDUALES
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s73_final_merge_pairs;
CREATE TEMP TABLE s73_final_merge_pairs
(
    canonical_normalized VARCHAR(255) PRIMARY KEY,
    duplicate_normalized VARCHAR(255) UNIQUE NOT NULL,
    final_name           VARCHAR(255)        NOT NULL
) ON COMMIT DROP;

INSERT INTO s73_final_merge_pairs (canonical_normalized,
                                   duplicate_normalized,
                                   final_name)
VALUES ('antoine dole', 'dole antoine', 'Antoine Dolé'),
       ('lola moral', 'moral lola', 'Lola Moral');

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM (SELECT p.canonical_normalized,
                                COUNT(DISTINCT c.id) AS canonical_matches,
                                p.duplicate_normalized,
                                COUNT(DISTINCT d.id) AS duplicate_matches
                         FROM s73_final_merge_pairs p
                                  LEFT JOIN authors c
                                            ON c.name_normalized = p.canonical_normalized
                                  LEFT JOIN authors d
                                            ON d.name_normalized = p.duplicate_normalized
                         GROUP BY p.canonical_normalized,
                                  p.duplicate_normalized
                         HAVING COUNT(DISTINCT c.id) <> 1
                             OR COUNT(DISTINCT d.id) > 1) x) THEN
            RAISE EXCEPTION
                'Abortado: algún merge individual no resuelve exactamente una vez';
        END IF;
    END
$$;

DROP TABLE IF EXISTS pg_temp.s73_resolved_final_merges;
CREATE TEMP TABLE s73_resolved_final_merges ON COMMIT DROP AS
SELECT p.final_name,
       p.canonical_normalized,
       p.duplicate_normalized,
       c.id AS canonical_id,
       d.id AS duplicate_id
FROM s73_final_merge_pairs p
         JOIN authors c
              ON c.name_normalized = p.canonical_normalized
         JOIN authors d
              ON d.name_normalized = p.duplicate_normalized;


-- Copiar relaciones al canónico
INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                r.canonical_id
FROM s73_resolved_final_merges r
         JOIN book_authors ba
              ON ba.author_id = r.duplicate_id
ON CONFLICT (book_id, author_id) DO NOTHING;

-- Validar copia
DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s73_resolved_final_merges r
                            JOIN book_authors bd
                                 ON bd.author_id = r.duplicate_id
                            LEFT JOIN book_authors bc
                                      ON bc.book_id = bd.book_id
                                          AND bc.author_id = r.canonical_id
                   WHERE bc.book_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: algún libro no fue copiado al autor canónico';
        END IF;
    END
$$;

-- Borrar relaciones y duplicados
DELETE
FROM book_authors ba
    USING s73_resolved_final_merges r
WHERE ba.author_id = r.duplicate_id;

DELETE
FROM authors a
    USING s73_resolved_final_merges r
WHERE a.id = r.duplicate_id;

UPDATE authors a
SET name            = r.final_name,
    name_normalized = r.canonical_normalized
FROM s73_resolved_final_merges r
WHERE a.id = r.canonical_id;

