-- ============================================================
-- C) VALIDAR FUENTES
-- ============================================================
-- La fuente puede estar ausente si el lote ya fue aplicado.
-- Nunca puede resolver a más de un registro físico.
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s74_composite_groups g
                            LEFT JOIN authors a
                                      ON a.name_normalized = g.composite_name_normalized
                   GROUP BY g.group_id,
                            g.composite_name_normalized
                   HAVING COUNT(a.id) > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna fuente compuesta de Script-74 resuelve ambiguamente';
        END IF;
    END
$$;


-- ============================================================
-- D) VALIDAR TARGETS
-- ============================================================
-- Cada autor individual debe existir exactamente una vez.
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               'group_id=%s, target=%s, matches=%s',
                               x.group_id,
                               x.target_name_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.group_id,
                           x.target_name_normalized
               )
        INTO invalid_targets
        FROM (SELECT ct.group_id,
                     ct.target_name_normalized,
                     COUNT(a.id) AS matches
              FROM s74_composite_targets ct
                       LEFT JOIN authors a
                                 ON a.name_normalized = ct.target_name_normalized
              GROUP BY ct.group_id,
                       ct.target_name_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'Abortado: Script-74 targets sin resolver exactamente una vez: %',
                invalid_targets;
        END IF;
    END
$$;


-- ============================================================
-- E) RESOLVER FUENTES Y TARGETS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s74_resolved_composites;

CREATE TEMP TABLE s74_resolved_composites ON COMMIT DROP AS
SELECT g.group_id,
       a.id              AS composite_author_id,
       a.name            AS composite_author_name,
       a.name_normalized AS composite_name_normalized
FROM s74_composite_groups g
         JOIN authors a
              ON a.name_normalized = g.composite_name_normalized;


DROP TABLE IF EXISTS pg_temp.s74_resolved_targets;

CREATE TEMP TABLE s74_resolved_targets ON COMMIT DROP AS
SELECT ct.group_id,
       a.id              AS target_author_id,
       a.name            AS target_author_name,
       a.name_normalized AS target_name_normalized
FROM s74_composite_targets ct
         JOIN authors a
              ON a.name_normalized = ct.target_name_normalized;


-- ============================================================
-- F) SNAPSHOT LIBRO -> TARGET
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s74_composite_book_targets;

CREATE TEMP TABLE s74_composite_book_targets ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.group_id,
                rc.composite_author_id,
                rt.target_author_id
FROM s74_resolved_composites rc
         JOIN book_authors ba
              ON ba.author_id = rc.composite_author_id
         JOIN s74_resolved_targets rt
              ON rt.group_id = rc.group_id;


-- ============================================================
-- G) CREAR RELACIONES INDIVIDUALES
-- ============================================================

INSERT INTO book_authors (book_id, author_id)
SELECT cbt.book_id,
       cbt.target_author_id
FROM s74_composite_book_targets cbt
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- H) POSTCONDICIÓN ANTES DE BORRAR
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s74_composite_book_targets cbt
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = cbt.book_id
                                          AND ba.author_id = cbt.target_author_id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: algún libro de Script-74 no recibió todos sus autores individuales';
        END IF;
    END
$$;


-- ============================================================
-- I) ELIMINAR RELACIONES A LOS COMPUESTOS
-- ============================================================

DELETE
FROM book_authors ba
    USING s74_resolved_composites rc
WHERE ba.author_id = rc.composite_author_id;


DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s74_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_author_id) THEN
            RAISE EXCEPTION
                'Abortado: quedaron relaciones hacia autores compuestos de Script-74';
        END IF;
    END
$$;


-- ============================================================
-- J) ELIMINAR AUTORES COMPUESTOS
-- ============================================================

DELETE
FROM authors a
    USING s74_resolved_composites rc
WHERE a.id = rc.composite_author_id;


-- ============================================================
-- K) POSTCONDICIONES FINALES
-- ============================================================

DO
$$
    BEGIN
        -- Ninguna fuente histórica debe seguir existiendo.
        IF EXISTS (SELECT 1
                   FROM s74_composite_groups g
                            JOIN authors a
                                 ON a.name_normalized = g.composite_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron autores compuestos sin eliminar en Script-74';
        END IF;

        -- Todos los targets deben seguir existiendo exactamente una vez.
        IF EXISTS (SELECT 1
                   FROM s74_composite_targets ct
                            LEFT JOIN authors a
                                      ON a.name_normalized = ct.target_name_normalized
                   GROUP BY ct.group_id,
                            ct.target_name_normalized
                   HAVING COUNT(a.id) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: Script-74 terminó con targets individuales inconsistentes';
        END IF;
    END
$$;


