-- ============================================================
-- A) VALIDAR QUE NO HAYA RESOLUCIONES AMBIGUAS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s76_author_merge_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.canonical_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.duplicate_name_normalized) > 1
                      OR (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) > 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla de Script-76 resuelve ambiguamente';
        END IF;
    END
$$;


-- ============================================================
-- B) RESOLVER LOS REGISTROS FÍSICOS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s76_author_merges;

CREATE TEMP TABLE s76_author_merges
(
    canonical_name_normalized VARCHAR(255) NOT NULL,
    duplicate_name_normalized VARCHAR(255) NOT NULL,
    final_name                VARCHAR(255) NOT NULL,
    final_name_normalized     VARCHAR(255) NOT NULL,

    canonical_id              BIGINT,
    duplicate_id              BIGINT,
    final_id                  BIGINT,

    resolved_canonical_id     BIGINT
) ON COMMIT DROP;


INSERT INTO s76_author_merges (canonical_name_normalized,
                               duplicate_name_normalized,
                               final_name,
                               final_name_normalized,
                               canonical_id,
                               duplicate_id,
                               final_id,
                               resolved_canonical_id)
SELECT r.canonical_name_normalized,
       r.duplicate_name_normalized,
       r.final_name,
       r.final_name_normalized,

       c.id,
       d.id,
       f.id,

       COALESCE(c.id, f.id, d.id)

FROM s76_author_merge_rules r

         LEFT JOIN authors c
                   ON c.name_normalized = r.canonical_name_normalized

         LEFT JOIN authors d
                   ON d.name_normalized = r.duplicate_name_normalized

         LEFT JOIN authors f
                   ON f.name_normalized = r.final_name_normalized;


-- ============================================================
-- C) TODA REGLA DEBE ENCONTRAR AL MENOS UN AUTOR
-- ============================================================

DO
$$
    DECLARE
        unresolved TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               'canonical=%s, duplicate=%s, final=%s',
                               canonical_name_normalized,
                               duplicate_name_normalized,
                               final_name_normalized
                       ),
                       ' | '
                       ORDER BY canonical_name_normalized
               )
        INTO unresolved
        FROM s76_author_merges
        WHERE resolved_canonical_id IS NULL;

        IF unresolved IS NOT NULL THEN
            RAISE EXCEPTION
                'Abortado: Script-76 no encuentra candidatos para: %',
                unresolved;
        END IF;
    END
$$;


-- ============================================================
-- D) COPIAR RELACIONES AL CANÓNICO
-- ============================================================

INSERT INTO book_authors (book_id, author_id)
SELECT DISTINCT ba.book_id,
                am.resolved_canonical_id
FROM s76_author_merges am
         JOIN book_authors ba
              ON ba.author_id IN (
                                  am.canonical_id,
                                  am.duplicate_id,
                                  am.final_id
                  )
WHERE am.resolved_canonical_id IS NOT NULL
  AND ba.author_id <> am.resolved_canonical_id
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- E) VERIFICAR QUE TODAS LAS RELACIONES FUERON COPIADAS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s76_author_merges am
                            JOIN book_authors source_ba
                                 ON source_ba.author_id IN (
                                                            am.canonical_id,
                                                            am.duplicate_id,
                                                            am.final_id
                                     )
                                     AND source_ba.author_id <> am.resolved_canonical_id

                            LEFT JOIN book_authors target_ba
                                      ON target_ba.book_id = source_ba.book_id
                                          AND target_ba.author_id = am.resolved_canonical_id

                   WHERE target_ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'Abortado: algún libro de Script-76 no fue copiado al autor canónico';
        END IF;
    END
$$;


-- ============================================================
-- F) ELIMINAR RELACIONES NO CANÓNICAS
-- ============================================================

DELETE
FROM book_authors ba
    USING s76_author_merges am
WHERE am.resolved_canonical_id IS NOT NULL
  AND ba.author_id IN (
                       am.canonical_id,
                       am.duplicate_id,
                       am.final_id
    )
  AND ba.author_id <> am.resolved_canonical_id;


-- ============================================================
-- G) ELIMINAR REGISTROS NO CANÓNICOS
-- ============================================================

DELETE
FROM authors a
    USING s76_author_merges am
WHERE am.resolved_canonical_id IS NOT NULL
  AND a.id IN (
               am.canonical_id,
               am.duplicate_id,
               am.final_id
    )
  AND a.id <> am.resolved_canonical_id;


-- ============================================================
-- H) APLICAR NOMBRE FINAL
-- ============================================================

UPDATE authors a
SET name            = am.final_name,
    name_normalized = am.final_name_normalized
FROM s76_author_merges am
WHERE a.id = am.resolved_canonical_id
  AND (
    a.name IS DISTINCT FROM am.final_name
        OR a.name_normalized IS DISTINCT FROM am.final_name_normalized
    );


-- ============================================================
-- I) POSTCONDICIONES
-- ============================================================

DO
$$
    BEGIN
        -- Cada regla debe terminar con exactamente un autor final.
        IF EXISTS (SELECT 1
                   FROM s76_author_merge_rules r
                   WHERE (SELECT COUNT(*)
                          FROM authors a
                          WHERE a.name_normalized = r.final_name_normalized) <> 1) THEN
            RAISE EXCEPTION
                'Abortado: alguna regla de Script-76 no terminó con exactamente un autor final';
        END IF;


        -- Ninguna variante histórica distinta del nombre final
        -- debe sobrevivir.
        IF EXISTS (SELECT 1
                   FROM s76_author_merge_rules r
                            JOIN authors a
                                 ON a.name_normalized IN (
                                                          r.canonical_name_normalized,
                                                          r.duplicate_name_normalized
                                     )
                   WHERE a.name_normalized <> r.final_name_normalized) THEN
            RAISE EXCEPTION
                'Abortado: quedaron variantes históricas sin consolidar en Script-76';
        END IF;
    END
$$;


-- ============================================================================
-- Historical cleanup batch Script-77
