-- ============================================================
-- 3) VALIDAR COMPUESTOS
-- ============================================================
-- Puede haber:
-- 0 -> ya eliminado por una ejecución anterior.
-- 1 -> estado esperado.
--
-- Nunca >1.
-- ============================================================

DO
$$
    DECLARE
        invalid_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.composite_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.composite_normalized
               )
        INTO invalid_composites
        FROM (SELECT c.composite_normalized,
                     COUNT(a.id) AS matches
              FROM s80_composites c
                       LEFT JOIN authors a
                                 ON a.name_normalized = c.composite_normalized
              GROUP BY c.composite_normalized
              HAVING COUNT(a.id) > 1) x;

        IF invalid_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-80 compuestos ambiguos: %',
                invalid_composites;
        END IF;
    END
$$;


-- ============================================================
-- 4) VALIDAR TARGETS ANTES DE CREAR
-- ============================================================
-- Pueden existir:
-- 0 -> hay que crearlos.
-- 1 -> reutilizamos el existente.
--
-- Nunca >1.
-- ============================================================

DO
$$
    DECLARE
        ambiguous_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO ambiguous_targets
        FROM (SELECT DISTINCT t.target_normalized,
                              COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s80_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) > 1) x;

        IF ambiguous_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-80 targets ambiguos: %',
                ambiguous_targets;
        END IF;
    END
$$;


-- ============================================================
-- 5) CREAR TARGETS FALTANTES
-- ============================================================

INSERT INTO authors (name,
                     name_normalized)
SELECT DISTINCT t.target_name,
                t.target_normalized
FROM s80_targets t
WHERE NOT EXISTS (SELECT 1
                  FROM authors a
                  WHERE a.name_normalized = t.target_normalized);


-- ============================================================
-- 6) POSTCONDICIÓN DE TARGETS
-- ============================================================
-- Después de la creación, cada target debe resolver exactamente una vez.
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (SELECT DISTINCT t.target_normalized,
                              COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s80_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-80 targets sin resolver: %',
                invalid_targets;
        END IF;
    END
$$;


-- ============================================================
-- 7) RESOLVER COMPUESTOS ACTIVOS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s80_resolved_composites;

CREATE TEMP TABLE s80_resolved_composites ON COMMIT DROP AS
SELECT c.composite_normalized,
       a.id   AS composite_id,
       a.name AS composite_name
FROM s80_composites c
         JOIN authors a
              ON a.name_normalized = c.composite_normalized;


-- ============================================================
-- 8) RESOLVER TARGETS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s80_resolved_targets;

CREATE TEMP TABLE s80_resolved_targets ON COMMIT DROP AS
SELECT t.composite_normalized,
       t.target_normalized,
       a.id   AS target_id,
       a.name AS target_name
FROM s80_targets t
         JOIN authors a
              ON a.name_normalized = t.target_normalized;


-- ============================================================
-- 9) SNAPSHOT LIBRO -> TARGET
-- ============================================================
-- Se toma antes de borrar cualquier relación al compuesto.
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s80_book_target_snapshot;

CREATE TEMP TABLE s80_book_target_snapshot ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.composite_id,
                rc.composite_normalized,
                rt.target_id
FROM s80_resolved_composites rc
         JOIN book_authors ba
              ON ba.author_id = rc.composite_id
         JOIN s80_resolved_targets rt
              ON rt.composite_normalized = rc.composite_normalized;


-- ============================================================
-- 10) COPIAR RELACIONES A AUTORES INDIVIDUALES
-- ============================================================

INSERT INTO book_authors (book_id,
                          author_id)
SELECT s.book_id,
       s.target_id
FROM s80_book_target_snapshot s
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- 11) VALIDAR QUE TODOS LOS TARGETS FUERON COPIADOS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s80_book_target_snapshot s

                            LEFT JOIN book_authors ba
                                      ON ba.book_id = s.book_id
                                          AND ba.author_id = s.target_id

                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'V69/Script-80: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;


-- ============================================================
-- 12) ELIMINAR RELACIONES AL COMPUESTO
-- ============================================================

DELETE
FROM book_authors ba
    USING s80_resolved_composites rc
WHERE ba.author_id = rc.composite_id;


-- ============================================================
-- 13) VALIDAR QUE NO QUEDEN RELACIONES AL COMPUESTO
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s80_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_id) THEN
            RAISE EXCEPTION
                'V69/Script-80: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;


-- ============================================================
-- 14) ELIMINAR AUTORES COMPUESTOS
-- ============================================================

DELETE
FROM authors a
    USING s80_resolved_composites rc
WHERE a.id = rc.composite_id;


-- ============================================================
-- 15) POSTCONDICIONES FINALES
-- ============================================================

DO
$$
    DECLARE
        remaining_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       c.composite_normalized,
                       ' | '
                       ORDER BY c.composite_normalized
               )
        INTO remaining_composites
        FROM s80_composites c
                 JOIN authors a
                      ON a.name_normalized = c.composite_normalized;

        IF remaining_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-80 quedaron compuestos sin eliminar: %',
                remaining_composites;
        END IF;
    END
$$;


DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s80_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-80 postcondición de targets fallida: %',
                invalid_targets;
        END IF;
    END
$$;


