        'diego gonzalez'),

       ('kirkman adlard',
        'Robert Kirkman',
        'kirkman robert'),

       ('kirkman adlard',
        'Charlie Adlard',
        'charlie adlard');


-- ============================================================
-- VALIDAR QUE LOS COMPUESTOS NO SEAN AMBIGUOS
-- ============================================================

DO
$$
    DECLARE
        invalid_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, matches=%s',
                              x.composite_normalized,
                              x.matches),
                       ' | '
                       ORDER BY x.composite_normalized
               )
        INTO invalid_composites
        FROM (SELECT c.composite_normalized,
                     COUNT(a.id) AS matches
              FROM s81_composites c
                       LEFT JOIN authors a
                                 ON a.name_normalized = c.composite_normalized
              GROUP BY c.composite_normalized
              HAVING COUNT(a.id) > 1) x;

        IF invalid_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-81 compuestos ambiguos: %',
                invalid_composites;
        END IF;
    END
$$;


-- ============================================================
-- VALIDAR TARGETS EXISTENTES
-- ============================================================

DO
$$
    DECLARE
        ambiguous_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, matches=%s',
                              x.target_normalized,
                              x.matches),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO ambiguous_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s81_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) > 1) x;

        IF ambiguous_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-81 targets ambiguos: %',
                ambiguous_targets;
        END IF;
    END
$$;


-- ============================================================
-- CREAR TARGETS FALTANTES
-- ============================================================

INSERT INTO authors (name, name_normalized)
SELECT DISTINCT t.target_name,
                t.target_normalized
FROM s81_targets t
WHERE NOT EXISTS (SELECT 1
                  FROM authors a
                  WHERE a.name_normalized = t.target_normalized);


-- ============================================================
-- VALIDAR QUE TODOS LOS TARGETS EXISTAN EXACTAMENTE UNA VEZ
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, matches=%s',
                              x.target_normalized,
                              x.matches),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s81_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-81 targets sin resolver: %',
                invalid_targets;
        END IF;
    END
$$;


-- ============================================================
-- RESOLVER COMPUESTOS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s81_resolved_composites;

CREATE TEMP TABLE s81_resolved_composites ON COMMIT DROP AS
SELECT c.composite_normalized,
       a.id AS composite_id
FROM s81_composites c
         JOIN authors a
              ON a.name_normalized = c.composite_normalized;


-- ============================================================
-- RESOLVER TARGETS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s81_resolved_targets;

CREATE TEMP TABLE s81_resolved_targets ON COMMIT DROP AS
SELECT t.composite_normalized,
       a.id AS target_id
FROM s81_targets t
         JOIN authors a
              ON a.name_normalized = t.target_normalized;


-- ============================================================
-- SNAPSHOT LIBRO -> TARGET
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s81_book_target_snapshot;

CREATE TEMP TABLE s81_book_target_snapshot ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.composite_id,
                rt.target_id
FROM s81_resolved_composites rc
         JOIN book_authors ba
              ON ba.author_id = rc.composite_id
         JOIN s81_resolved_targets rt
              ON rt.composite_normalized = rc.composite_normalized;


-- ============================================================
-- COPIAR RELACIONES
-- ============================================================

INSERT INTO book_authors (book_id, author_id)
SELECT s.book_id,
       s.target_id
FROM s81_book_target_snapshot s
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- VALIDAR COPIA
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s81_book_target_snapshot s
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = s.book_id
                                          AND ba.author_id = s.target_id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'V69/Script-81: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;


-- ============================================================
-- BORRAR RELACIONES A COMPUESTOS
-- ============================================================

DELETE
FROM book_authors ba
    USING s81_resolved_composites rc
WHERE ba.author_id = rc.composite_id;


-- ============================================================
-- VALIDAR QUE NO QUEDEN RELACIONES
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s81_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_id) THEN
            RAISE EXCEPTION
                'V69/Script-81: quedaron relaciones hacia compuestos';
        END IF;
    END
$$;


-- ============================================================
-- BORRAR COMPUESTOS
-- ============================================================

DELETE
FROM authors a
    USING s81_resolved_composites rc
WHERE a.id = rc.composite_id;


-- ============================================================
-- POSTCONDICIÓN FINAL
-- ============================================================

DO
$$
    DECLARE
        remaining TEXT;
    BEGIN
        SELECT STRING_AGG(
                       c.composite_normalized,
                       ' | '
                       ORDER BY c.composite_normalized
               )
        INTO remaining
        FROM s81_composites c
                 JOIN authors a
                      ON a.name_normalized = c.composite_normalized;

        IF remaining IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-81 quedaron compuestos: %',
                remaining;
        END IF;
    END
$$;


