-- ============================================================
-- 3) VALIDAR COMPUESTOS
-- ============================================================
-- 0 = ya limpiado en una ejecución previa.
-- 1 = estado normal.
-- >1 = ambiguo -> abortar.
-- ============================================================

DO
$$
    DECLARE
        invalid_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.composite_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.composite_normalized
               )
        INTO invalid_composites
        FROM (SELECT c.composite_normalized,
                     COUNT(a.id) AS matches
              FROM s82_composites c
                       LEFT JOIN authors a
                                 ON a.name_normalized = c.composite_normalized
              GROUP BY c.composite_normalized
              HAVING COUNT(a.id) > 1) x;

        IF invalid_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-82 compuestos ambiguos: %',
                invalid_composites;
        END IF;
    END
$$;


-- ============================================================
-- 4) VALIDAR TARGETS ANTES DE CREAR
-- ============================================================
-- 0 = puede crearse.
-- 1 = reutilizar.
-- >1 = ambiguo -> abortar.
-- ============================================================

DO
$$
    DECLARE
        ambiguous_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO ambiguous_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s82_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) > 1) x;

        IF ambiguous_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-82 targets ambiguos: %',
                ambiguous_targets;
        END IF;
    END
$$;


-- ============================================================
-- 5) CREAR ÚNICAMENTE LOS TARGETS REALMENTE AUSENTES
-- ============================================================

INSERT INTO authors (name,
                     name_normalized)
SELECT DISTINCT t.target_name,
                t.target_normalized
FROM s82_targets t
WHERE NOT EXISTS (SELECT 1
                  FROM authors a
                  WHERE a.name_normalized = t.target_normalized);


-- ============================================================
-- 6) TODOS LOS TARGETS DEBEN EXISTIR EXACTAMENTE UNA VEZ
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s82_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-82 targets sin resolver: %',
                invalid_targets;
        END IF;
    END
$$;


-- ============================================================
-- 7) RESOLVER COMPUESTOS ACTIVOS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s82_resolved_composites;

CREATE TEMP TABLE s82_resolved_composites ON COMMIT DROP AS
SELECT c.composite_normalized,
       a.id   AS composite_id,
       a.name AS composite_name
FROM s82_composites c
         JOIN authors a
              ON a.name_normalized = c.composite_normalized;


-- ============================================================
-- 8) RESOLVER TARGETS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s82_resolved_targets;

CREATE TEMP TABLE s82_resolved_targets ON COMMIT DROP AS
SELECT t.composite_normalized,
       t.target_normalized,
       a.id   AS target_id,
       a.name AS target_name
FROM s82_targets t
         JOIN authors a
              ON a.name_normalized = t.target_normalized;


-- ============================================================
-- 9) SNAPSHOT LIBRO -> TARGET
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s82_book_target_snapshot;

CREATE TEMP TABLE s82_book_target_snapshot ON COMMIT DROP AS
SELECT DISTINCT ba.book_id,
                rc.composite_id,
                rc.composite_normalized,
                rt.target_id
FROM s82_resolved_composites rc
         JOIN book_authors ba
              ON ba.author_id = rc.composite_id
         JOIN s82_resolved_targets rt
              ON rt.composite_normalized = rc.composite_normalized;


-- ============================================================
-- 10) COPIAR RELACIONES
-- ============================================================

INSERT INTO book_authors (book_id,
                          author_id)
SELECT s.book_id,
       s.target_id
FROM s82_book_target_snapshot s
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- 11) VALIDAR COPIA
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s82_book_target_snapshot s
                            LEFT JOIN book_authors ba
                                      ON ba.book_id = s.book_id
                                          AND ba.author_id = s.target_id
                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'V69/Script-82: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;


-- ============================================================
-- 12) BORRAR RELACIONES A LOS COMPUESTOS
-- ============================================================

DELETE
FROM book_authors ba
    USING s82_resolved_composites rc
WHERE ba.author_id = rc.composite_id;


-- ============================================================
-- 13) VALIDAR QUE NO QUEDEN RELACIONES A COMPUESTOS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s82_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_id) THEN
            RAISE EXCEPTION
                'V69/Script-82: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;


-- ============================================================
-- 14) BORRAR AUTORES COMPUESTOS
-- ============================================================

DELETE
FROM authors a
    USING s82_resolved_composites rc
WHERE a.id = rc.composite_id;


-- ============================================================
-- 15) POSTCONDICIÓN: NO QUEDAN COMPUESTOS DEL LOTE
-- ============================================================

DO
$$
    DECLARE
        remaining_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       c.composite_normalized,
                       ' | '
                       ORDER BY c.composite_normalized
               )
        INTO remaining_composites
        FROM s82_composites c
                 JOIN authors a
                      ON a.name_normalized = c.composite_normalized;

        IF remaining_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-82 quedaron compuestos sin eliminar: %',
                remaining_composites;
        END IF;
    END
$$;


-- ============================================================
-- 16) POSTCONDICIÓN: TODOS LOS TARGETS SIGUEN SIENDO ÚNICOS
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s82_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-82 postcondición de targets fallida: %',
                invalid_targets;
        END IF;
    END
$$;


