                   WHERE ba.book_id IS NULL) THEN
            RAISE EXCEPTION
                'V69/Script-84: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;


-- ============================================================
-- 12) ELIMINAR RELACIONES A COMPUESTOS
-- ============================================================

DELETE
FROM book_authors ba
    USING s84_resolved_composites rc
WHERE ba.author_id = rc.composite_id;


-- ============================================================
-- 13) VALIDAR AUSENCIA DE RELACIONES A COMPUESTOS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (SELECT 1
                   FROM s84_resolved_composites rc
                            JOIN book_authors ba
                                 ON ba.author_id = rc.composite_id) THEN
            RAISE EXCEPTION
                'V69/Script-84: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;


-- ============================================================
-- 14) ELIMINAR COMPUESTOS
-- ============================================================

DELETE
FROM authors a
    USING s84_resolved_composites rc
WHERE a.id = rc.composite_id;


-- ============================================================
-- 15) POSTCONDICIÓN DE COMPUESTOS
-- ============================================================

DO
$$
    DECLARE
        remaining_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       c.composite_normalized,
                       ' | '
                       ORDER BY c.composite_normalized
               )
        INTO remaining_composites
        FROM s84_composites c
                 JOIN authors a
                      ON a.name_normalized = c.composite_normalized;

        IF remaining_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-84 quedaron compuestos sin eliminar: %',
                remaining_composites;
        END IF;
    END
$$;


-- ============================================================
-- 16) POSTCONDICIÓN DE TARGETS
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT(
                               '%s, matches=%s',
                               x.target_normalized,
                               x.matches
                       ),
                       ' | '
                       ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (SELECT t.target_normalized,
                     COUNT(a.id) AS matches
              FROM (SELECT DISTINCT target_normalized
                    FROM s84_targets) t
                       LEFT JOIN authors a
                                 ON a.name_normalized = t.target_normalized
              GROUP BY t.target_normalized
              HAVING COUNT(a.id) <> 1) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-84 postcondición de targets fallida: %',
                invalid_targets;
        END IF;
    END
$$;


