-- ============================================================
-- 3) VALIDAR COMPUESTOS
-- ============================================================
-- 0 = ya fue eliminado por una ejecución previa.
-- 1 = estado esperado.
-- >1 = ambiguo -> abortar.
-- ============================================================

DO
$$
    DECLARE
        invalid_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, matches=%s', x.composite_normalized, x.matches),
                       ' | ' ORDER BY x.composite_normalized
               )
        INTO invalid_composites
        FROM (
                 SELECT c.composite_normalized,
                        COUNT(a.id) AS matches
                 FROM s85_composites c
                          LEFT JOIN authors a
                                    ON a.name_normalized = c.composite_normalized
                 GROUP BY c.composite_normalized
                 HAVING COUNT(a.id) > 1
             ) x;

        IF invalid_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-85 compuestos ambiguos: %',
                invalid_composites;
        END IF;
    END
$$;


-- ============================================================
-- 4) VALIDAR TARGETS
-- ============================================================
-- Todos los targets de este lote ya deben existir exactamente una vez.
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, matches=%s', x.target_normalized, x.matches),
                       ' | ' ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (
                 SELECT t.target_normalized,
                        COUNT(a.id) AS matches
                 FROM (
                          SELECT DISTINCT target_normalized
                          FROM s85_targets
                      ) t
                          LEFT JOIN authors a
                                    ON a.name_normalized = t.target_normalized
                 GROUP BY t.target_normalized
                 HAVING COUNT(a.id) <> 1
             ) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-85 targets sin resolver o ambiguos: %',
                invalid_targets;
        END IF;
    END
$$;


-- ============================================================
-- 5) RESOLVER COMPUESTOS ACTIVOS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s85_resolved_composites;

CREATE TEMP TABLE s85_resolved_composites ON COMMIT DROP AS
SELECT c.composite_normalized,
       a.id AS composite_id
FROM s85_composites c
         JOIN authors a
              ON a.name_normalized = c.composite_normalized;


-- ============================================================
-- 6) RESOLVER TARGETS
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s85_resolved_targets;

CREATE TEMP TABLE s85_resolved_targets ON COMMIT DROP AS
SELECT t.composite_normalized,
       t.target_normalized,
       a.id AS target_id
FROM s85_targets t
         JOIN authors a
              ON a.name_normalized = t.target_normalized;


-- ============================================================
-- 7) VALIDAR COBERTURA DE REGLAS
-- ============================================================
-- Cada compuesto activo debe tener al menos dos targets resueltos.
-- ============================================================

DO
$$
    DECLARE
        invalid_rules TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, targets=%s', x.composite_normalized, x.target_count),
                       ' | ' ORDER BY x.composite_normalized
               )
        INTO invalid_rules
        FROM (
                 SELECT rc.composite_normalized,
                        COUNT(rt.target_id) AS target_count
                 FROM s85_resolved_composites rc
                          LEFT JOIN s85_resolved_targets rt
                                    ON rt.composite_normalized = rc.composite_normalized
                 GROUP BY rc.composite_normalized
                 HAVING COUNT(rt.target_id) < 2
             ) x;

        IF invalid_rules IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-85 reglas incompletas: %',
                invalid_rules;
        END IF;
    END
$$;


-- ============================================================
-- 8) SNAPSHOT LIBRO -> TARGET
-- ============================================================

DROP TABLE IF EXISTS pg_temp.s85_book_target_snapshot;

CREATE TEMP TABLE s85_book_target_snapshot ON COMMIT DROP AS
SELECT DISTINCT
    ba.book_id,
    rc.composite_id,
    rc.composite_normalized,
    rt.target_id
FROM s85_resolved_composites rc
         JOIN book_authors ba
              ON ba.author_id = rc.composite_id
         JOIN s85_resolved_targets rt
              ON rt.composite_normalized = rc.composite_normalized;


-- ============================================================
-- 9) COPIAR RELACIONES A AUTORES INDIVIDUALES
-- ============================================================

INSERT INTO book_authors (
    book_id,
    author_id
)
SELECT s.book_id,
       s.target_id
FROM s85_book_target_snapshot s
ON CONFLICT (book_id, author_id) DO NOTHING;


-- ============================================================
-- 10) VALIDAR COPIA
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM s85_book_target_snapshot s
                     LEFT JOIN book_authors ba
                               ON ba.book_id = s.book_id
                                   AND ba.author_id = s.target_id
            WHERE ba.book_id IS NULL
        ) THEN
            RAISE EXCEPTION
                'V69/Script-85: algún libro no recibió todos sus autores individuales';
        END IF;
    END
$$;


-- ============================================================
-- 11) ELIMINAR RELACIONES A COMPUESTOS
-- ============================================================

DELETE FROM book_authors ba
    USING s85_resolved_composites rc
WHERE ba.author_id = rc.composite_id;


-- ============================================================
-- 12) VALIDAR AUSENCIA DE RELACIONES A COMPUESTOS
-- ============================================================

DO
$$
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM s85_resolved_composites rc
                     JOIN book_authors ba
                          ON ba.author_id = rc.composite_id
        ) THEN
            RAISE EXCEPTION
                'V69/Script-85: quedaron relaciones hacia autores compuestos';
        END IF;
    END
$$;


-- ============================================================
-- 13) ELIMINAR AUTORES COMPUESTOS
-- ============================================================

DELETE FROM authors a
    USING s85_resolved_composites rc
WHERE a.id = rc.composite_id;


-- ============================================================
-- 14) POSTCONDICIÓN: COMPUESTOS ELIMINADOS
-- ============================================================

DO
$$
    DECLARE
        remaining_composites TEXT;
    BEGIN
        SELECT STRING_AGG(
                       c.composite_normalized,
                       ' | ' ORDER BY c.composite_normalized
               )
        INTO remaining_composites
        FROM s85_composites c
                 JOIN authors a
                      ON a.name_normalized = c.composite_normalized;

        IF remaining_composites IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-85 quedaron compuestos sin eliminar: %',
                remaining_composites;
        END IF;
    END
$$;


-- ============================================================
-- 15) POSTCONDICIÓN: TARGETS ÚNICOS
-- ============================================================

DO
$$
    DECLARE
        invalid_targets TEXT;
    BEGIN
        SELECT STRING_AGG(
                       FORMAT('%s, matches=%s', x.target_normalized, x.matches),
                       ' | ' ORDER BY x.target_normalized
               )
        INTO invalid_targets
        FROM (
                 SELECT t.target_normalized,
                        COUNT(a.id) AS matches
                 FROM (
                          SELECT DISTINCT target_normalized
                          FROM s85_targets
                      ) t
                          LEFT JOIN authors a
                                    ON a.name_normalized = t.target_normalized
                 GROUP BY t.target_normalized
                 HAVING COUNT(a.id) <> 1
             ) x;

        IF invalid_targets IS NOT NULL THEN
            RAISE EXCEPTION
                'V69/Script-85 postcondición de targets fallida: %',
                invalid_targets;
        END IF;
    END
$$;